    def _process_overdue_payment_async(overdue_accounts: list, auth_username: str, out_trade_no: str):
        logging.info(f"[overdue_count处理] 欠费账号列表: {overdue_accounts}")
        # 提取总欠费次数（订单创建时已计算好）
        total_count = 0
        for account in overdue_accounts:
            account_overdue_count = account.get("overdue_count", 0)
            total_count += account_overdue_count

        # 验证必要字段是否存在
        if overdue_accounts and total_count > 0:
            try:

                # 遍历所有欠费账号

                for account in overdue_accounts:
                    # 提取学校账号用户名
                    school_username = account.get(
                        "school_username", "")

                    # 验证学校账号用户名是否有效
                    if not school_username:
                        # 如果用户名为空，跳过该账号
                        continue

                    # 构造学校账号INI文件路径
                    # INI文件存储在SCHOOL_ACCOUNTS_DIR目录下，以{school_username}.ini命名
                    account_ini_path = os.path.join(
                        _main().SCHOOL_ACCOUNTS_DIR, f"{school_username}.ini")

                    # 检查INI文件是否存在
                    if os.path.exists(account_ini_path):
                        try:
                            # 读取INI文件
                            # ConfigParser是Python标准库，用于读写INI格式的配置文件
                            account_config = configparser.ConfigParser(
                                strict=False)
                            account_config.read(
                                account_ini_path, encoding="utf-8")

                            # 读取当前的overdue_count值
                            # 从[stats]节中读取overdue_count字段
                            # 如果字段不存在，默认值为0
                            current_overdue_count = 0
                            if account_config.has_option("stats", "overdue_count"):
                                current_overdue_count = int(
                                    account_config.get("stats", "overdue_count", fallback="0"))

                            # 从订单的overdue_accounts中获取该账号的overdue_count
                            # 这个值表示该账号在此订单中的欠费次数
                            # 支付成功后，需要减去这个值，而不是固定减1
                            account_overdue_count = account.get(
                                "overdue_count", 0)

                            # 计算新的overdue_count值
                            # 使用max(0, ...)确保结果不会小于0
                            # 减去的值是订单中该账号对应的overdue_count，而不是固定减1
                            new_overdue_count = max(
                                0, current_overdue_count - account_overdue_count)

                            # 确保[stats]节存在
                            # 如果INI文件中没有[stats]节，则创建它
                            if not account_config.has_section("stats"):
                                account_config.add_section("stats")

                            # 设置新的overdue_count值
                            # 将计算好的新值写入配置对象
                            account_config.set(
                                "stats", "overdue_count", str(new_overdue_count))

                            # 将配置写回文件
                            # 这一步将内存中的配置对象持久化到磁盘
                            with open(account_ini_path, "w", encoding="utf-8") as f:
                                account_config.write(f)

                            # 记录日志：更新成功
                            # 日志中包含账号名、原值、减少值和新值，便于追踪和调试
                            logging.info(
                                f"[订单overdue处理] 账号 {school_username} 的overdue_count: "
                                f"{current_overdue_count} - {account_overdue_count} = {new_overdue_count}"
                            )

                        except Exception as e:
                            # 捕获处理单个账号时的异常
                            # 即使某个账号处理失败，也不影响其他账号的处理
                            logging.error(
                                f"[订单overdue处理] 处理账号 {school_username} 失败: {str(e)}"
                            )
                    else:
                        # INI文件不存在
                        # 这可能是因为账号已被删除，或者数据迁移时文件丢失
                        logging.warning(
                            f"[订单overdue处理] 账号文件不存在: {account_ini_path}"
                        )

                # ========== 步骤3：记录欠费支付成功日志 ==========

                # 记录总结日志
                logging.info(
                    f"[欠费支付-异步] 欠费补缴处理完成 - 学校账号: {overdue_accounts}, "
                    f"总欠费次数: {total_count}, 用户: {auth_username}, 订单: {out_trade_no}"
                )

            except Exception as e:
                # 捕获欠费处理过程中的异常
                # 即使处理失败，也不影响异步线程的执行
                # 但需要记录详细的错误日志，便于人工介入处理
                logging.error(
                    f"[欠费支付-异步] 处理欠费补缴异常 - 用户: {auth_username}, "
                    f"订单: {out_trade_no}, 错误: {str(e)}"
                )
                logging.error(traceback.format_exc())

                # 记录错误日志到支付操作日志
                _write_payment_log(
                    user_id=auth_username,
                    order_id=out_trade_no,
                    action="overdue_payment_error",
                    log_data={
                        "error": str(e),
                        "traceback": traceback.format_exc(),
                        "overdue_accounts": overdue_accounts
                    }
                )
        else:
            # 订单数据不完整（异常情况）
            logging.warning(
                f"[overdue_count处理] 订单数据不完整，无法处理欠费 - 订单: {out_trade_no}, "
                f"auth_username: {auth_username}, total_count: {total_count}"
            )

        # ========== 更新账单记录状态 ==========
        # 扫描该用户的账单目录，找到payment_orders中包含本订单号的记录，更新为已支付
        try:
            _billing_base_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "User_Billing", auth_username)
            _paid_at = _main()._billing_now_utc_string()
            _paid_at_beijing = _main()._billing_now_beijing_string()
            _order_unit_amount = None
            try:
                _order_path = os.path.join(PAYMENT_ORDERS_DIR, f"{out_trade_no}.json")
                if os.path.exists(_order_path):
                    with open(_order_path, "r", encoding="utf-8") as _of:
                        _order_data = json.load(_of)
                    _order_total_amount = float(_order_data.get("amount", 0))
                    _order_total_count = int(_order_data.get("total_count", 0))
                    if _order_total_count > 0:
                        _order_unit_amount = round(_order_total_amount / _order_total_count, 2)
            except Exception:
                _order_unit_amount = None
            if os.path.isdir(_billing_base_dir):
                for _bf in os.listdir(_billing_base_dir):
                    if not _bf.endswith(".json"):
                        continue
                    _bpath = os.path.join(_billing_base_dir, _bf)
                    try:
                        with open(_bpath, "r", encoding="utf-8") as _f:
                            _brec = json.load(_f)
                        # 找到包含本订单号的账单记录
                        if out_trade_no in _brec.get("payment_orders", []):
                            if _order_unit_amount is not None:
                                try:
                                    if round(float(_brec.get("amount", -1)), 2) != _order_unit_amount:
                                        continue
                                except Exception:
                                    continue
                            _brec["status"] = "paid"
                            _brec["final_payment_order"] = out_trade_no
                            _brec["paid_at"] = _paid_at
                            _brec["paid_at_beijing"] = _paid_at_beijing
                            with open(_bpath, "w", encoding="utf-8") as _f:
                                json.dump(_brec, _f, indent=2, ensure_ascii=False)
                            logging.info(f"[账单] 账单 {_brec.get('billing_id')} 已标记为已支付")
                    except Exception as _be:
                        logging.warning(f"[账单] 更新账单文件 {_bf} 失败: {_be}")
        except Exception as _e:
            logging.error(f"[账单] 更新账单状态失败: {_e}", exc_info=True)

        logging.info(f"[overdue_count处理] 订单处理完成 - 订单号: {out_trade_no}")

    def _process_billing_payment_async(billing_items: list, out_trade_no: str):
        """
        处理普通账单支付成功后的账单状态更新。
        """
        if not isinstance(billing_items, list) or not billing_items:
            return
        try:
            _paid_at = _main()._billing_now_utc_string()
            _paid_at_beijing = _main()._billing_now_beijing_string()
            for item in billing_items:
                school_username = str(item.get("school_username", "")).strip()
                billing_id = str(item.get("billing_id", "")).strip()
                if not school_username or not billing_id:
                    continue
                billing_file = os.path.join(
                    os.path.dirname(os.path.abspath(__file__)),
                    "User_Billing",
                    "School_Bills",
                    school_username,
                    f"{billing_id}.json",
                )
                if not os.path.exists(billing_file):
                    continue
                try:
                    with open(billing_file, "r", encoding="utf-8") as _f:
                        _brec = json.load(_f)
                    if _brec.get("status") != "pending":
                        continue
                    if out_trade_no not in (_brec.get("payment_orders") or []):
                        continue
                    _brec["status"] = "paid"
                    _brec["final_payment_order"] = out_trade_no
                    _brec["paid_at"] = _paid_at
                    _brec["paid_at_beijing"] = _paid_at_beijing
                    with open(billing_file, "w", encoding="utf-8") as _f:
                        json.dump(_brec, _f, indent=2, ensure_ascii=False)
                    logging.info(f"[账单支付] 账单 {billing_id} 已标记为已支付")
                except Exception as _be:
                    logging.warning(f"[账单支付] 更新账单文件 {billing_id}.json 失败: {_be}")
        except Exception as _e:
            logging.error(f"[账单支付] 批量更新账单状态失败: {_e}", exc_info=True)

    def parse_google_fonts_css(css_content, css_url, key):
        """
        解析CSS内容中的字体文件URL（支持绝对路径与相对路径）。

        参数:
            css_content: CSS文件内容
            css_url: CSS来源URL（用于解析相对路径）
            key: CDN缓存键名（用于生成稳定文件名）

        返回:
            字体URL列表 [(原始URL, 绝对URL, font_key), ...]
        """
        if not isinstance(css_content, str):
            return []

        # 同时匹配 url("..."), url('...'), url(...) 三种写法
        pattern = r"url\(\s*([\"']?)([^\"')]+)\1\s*\)"
        matches = re.findall(pattern, css_content)

        supported_exts = (".woff2", ".woff", ".ttf", ".otf")
        font_urls = []
        seen = set()

        for _, raw_url in matches:
            original_ref = (raw_url or "").strip()
            if not original_ref:
                continue

            # 跳过内联data URI、锚点和本地blob
            lowered = original_ref.lower()
            if lowered.startswith("data:") or lowered.startswith("blob:") or lowered.startswith("#"):
                continue

            # 解析相对路径为绝对URL，便于下载
            absolute_url = urllib.parse.urljoin(css_url, original_ref)
            parsed = urllib.parse.urlparse(absolute_url)
            path_lower = (parsed.path or "").lower()
            if not path_lower.endswith(supported_exts):
                continue

            base_name = os.path.basename(parsed.path)
            safe_key = re.sub(r"[^a-zA-Z0-9_-]", "-", str(key))
            url_hash = hashlib.sha256(absolute_url.encode("utf-8")).hexdigest()[:10]
            font_key = f"{safe_key}-{url_hash}-{base_name}"

            dedupe_key = (original_ref, absolute_url)
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)

            font_urls.append((original_ref, absolute_url, font_key))

        return font_urls

    def cache_google_fonts_with_ttf(css_content, key, css_url, css_filename):
        """
        缓存CSS中引用的字体文件（TTF/WOFF/WOFF2/OTF），并将URL改写为本地接口。
        
        优化策略：先将所有字体文件下载到临时目录，全部成功后再原子性地替换
        CSS和字体文件夹，避免下载中断导致的不一致状态。

        参数:
            css_content: CSS文件内容
            key: 缓存键名
            css_url: CSS来源URL（用于解析相对路径）
            css_filename: CSS缓存文件名（用于构建字体子目录）

        返回:
            处理后的CSS内容（URL已替换为本地API地址）
        """
        font_urls = parse_google_fonts_css(css_content, css_url, key)
        logging.info(f"[CDN缓存] 资源 {key} 发现 {len(font_urls)} 个字体文件需要缓存")

        if not font_urls:
            return css_content

        # 目录名取CSS文件基名，并去掉 .min.css 或 .css 后缀
        css_name = os.path.basename((css_filename or f"{key}.css").strip() or f"{key}.css")
        css_font_dir = re.sub(r"(?:\.min)?\.css$", "", css_name, flags=re.IGNORECASE).strip() or str(key)

        # 创建临时目录用于存放下载的字体文件
        temp_font_dir = os.path.join(JS_CACHE_DIR, f".tmp_{css_font_dir}_{int(time.time() * 1000)}")
        final_font_dir = os.path.join(JS_CACHE_DIR, css_font_dir)
        
        try:
            os.makedirs(temp_font_dir, exist_ok=True)
        except Exception as e:
            logging.error(f"[CDN缓存] 创建临时字体目录失败: {e}")
            return css_content

        # 第一阶段：下载所有字体到临时目录
        downloaded_fonts = []  # [(font_key, font_storage_key, font_content, temp_path), ...]
        download_success = True
        modified_css = css_content
        # 目录名取CSS文件基名，并去掉 .min.css 或 .css 后缀
        css_name = os.path.basename((css_filename or f"{key}.css").strip() or f"{key}.css")
        css_font_dir = re.sub(r"(?:\.min)?\.css$", "", css_name, flags=re.IGNORECASE).strip() or str(key)

        for original_ref, absolute_url, font_key in font_urls:
            logging.info(f"[CDN缓存] 正在下载字体到临时目录: {font_key}")
            font_content = fetch_cdn_file(absolute_url, timeout=60, binary=True)

            if font_content:
                font_relative_path = os.path.join(css_font_dir, font_key)
                font_storage_key = font_relative_path.replace("\\", "/").replace("/", "__")
                temp_font_path = os.path.join(temp_font_dir, font_key)
                
                try:
                    # 写入临时目录
                    with open(temp_font_path, "wb") as f:
                        f.write(font_content)
                    
                    downloaded_fonts.append((font_key, font_storage_key, font_content, temp_font_path))
                    
                    # 预先构建修改后的CSS（但不保存）
                    local_url = f"/api/cdn/font/{font_storage_key}"
                    modified_css = modified_css.replace(original_ref, local_url)
                    logging.info(f"[CDN缓存] 字体已下载到临时目录: {temp_font_path}")
                except Exception as e:
                    logging.error(f"[CDN缓存] 写入临时字体文件失败: {font_key}, 错误: {e}")
                    download_success = False
                    break
            else:
                logging.warning(f"[CDN缓存] 字体下载失败: {absolute_url}")
                download_success = False
                break

        # 第二阶段：如果所有字体下载成功，原子性替换
        if download_success and downloaded_fonts:
            try:
                # 备份旧字体目录（如果存在）
                backup_dir = None
                if os.path.exists(final_font_dir):
                    backup_dir = os.path.join(JS_CACHE_DIR, f".backup_{css_font_dir}_{int(time.time() * 1000)}")
                    try:
                        os.rename(final_font_dir, backup_dir)
                        logging.info(f"[CDN缓存] 已备份旧字体目录: {backup_dir}")
                    except Exception as e:
                        logging.warning(f"[CDN缓存] 备份旧字体目录失败: {e}")
                        backup_dir = None

                # 将临时目录重命名为最终目录
                os.rename(temp_font_dir, final_font_dir)
                logging.info(f"[CDN缓存] 字体目录替换成功: {final_font_dir}")

                # 更新内存缓存
                with font_cache_lock:
                    for font_key, font_storage_key, font_content, _ in downloaded_fonts:
                        font_cache_storage[font_storage_key] = font_content
                        logging.info(f"[CDN缓存] 字体已加入内存缓存: {font_storage_key}")

                # 删除备份目录
                if backup_dir and os.path.exists(backup_dir):
                    try:
                        shutil.rmtree(backup_dir)
                        logging.info(f"[CDN缓存] 已删除旧字体备份: {backup_dir}")
                    except Exception as e:
                        logging.warning(f"[CDN缓存] 删除备份目录失败: {backup_dir}, 错误: {e}")

                logging.info(f"[CDN缓存] 资源 {key} 的 {len(downloaded_fonts)} 个字体文件已全部原子性更新")
                return modified_css

            except Exception as e:
                logging.error(f"[CDN缓存] 原子替换字体目录失败: {e}")
                # 恢复备份
                if backup_dir and os.path.exists(backup_dir):
                    try:
                        if os.path.exists(final_font_dir):
                            shutil.rmtree(final_font_dir)
                        os.rename(backup_dir, final_font_dir)
                        logging.info(f"[CDN缓存] 已恢复备份字体目录")
                    except Exception as restore_e:
                        logging.error(f"[CDN缓存] 恢复备份失败: {restore_e}")
                # 清理临时目录
                try:
                    if os.path.exists(temp_font_dir):
                        shutil.rmtree(temp_font_dir)
                except Exception as cleanup_e:
                    logging.warning(f"[CDN缓存] 清理临时目录失败: {temp_font_dir}, 错误: {cleanup_e}")
                return css_content
        else:
            # 下载失败，清理临时目录
            logging.warning(f"[CDN缓存] 资源 {key} 字体下载未完全成功，保留原有CSS不做修改")
            try:
                if os.path.exists(temp_font_dir):
                    shutil.rmtree(temp_font_dir)
            except Exception as e:
                logging.warning(f"[CDN缓存] 清理临时目录失败: {temp_font_dir}, 错误: {e}")
            return css_content

    def load_cached_fonts():
        """
        从本地缓存加载所有字体文件
        """
        try:
            fonts_dir = JS_CACHE_DIR
            if not os.path.exists(fonts_dir):
                return

            for root, _, files in os.walk(fonts_dir):
                for filename in files:
                    if not (
                        filename.endswith(".ttf")
                        or filename.endswith(".woff")
                        or filename.endswith(".woff2")
                        or filename.endswith(".otf")
                    ):
                        continue

                    filepath = os.path.join(root, filename)
                    try:
                        with open(filepath, "rb") as f:
                            content = f.read()

                        rel_path = os.path.relpath(filepath, fonts_dir)
                        rel_path = rel_path.replace("\\", "/")
                        storage_key = rel_path.replace("/", "__")

                        with font_cache_lock:
                            font_cache_storage[storage_key] = content
                        logging.info(f"[CDN缓存] 从本地加载字体: {rel_path}")
                    except Exception as e:
                        logging.warning(f"[CDN缓存] 加载字体文件失败 {filepath}: {e}")
        except Exception as e:
            logging.warning(f"[CDN缓存] 扫描字体缓存目录失败: {e}")

    def fetch_cdn_file(url, timeout=30, binary=False):
        """
        从CDN获取文件内容

        参数:
            url: 文件URL
            timeout: 超时时间（秒）
            binary: 是否以二进制模式获取（用于字体文件等）
        """
        try:
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
            }
            response = _main().requests.get(url, headers=headers, timeout=timeout)
            if response.status_code == 200:
                return response.content if binary else response.text
            else:
                logging.warning(
                    f"[CDN缓存] 获取文件失败，状态码: {response.status_code}, URL: {url}"
                )
                return None
        except Exception as e:
            logging.error(f"[CDN缓存] 获取文件异常: {e}, URL: {url}")
            return None

    def load_cached_file(filename, binary=False):
        """
        从本地缓存文件加载内容

        参数:
            filename: 文件名
            binary: 是否以二进制模式读取
        """
        cache_path = os.path.join(JS_CACHE_DIR, filename)
        if os.path.exists(cache_path):
            try:
                mode = "rb" if binary else "r"
                encoding = None if binary else "utf-8"
                with open(cache_path, mode, encoding=encoding) as f:
                    return f.read()
            except Exception as e:
                logging.error(f"[CDN缓存] 读取缓存文件失败: {e}, 文件: {filename}")
        return None

    def save_cached_file(filename, content, binary=False):
        """
        保存内容到本地缓存文件

        参数:
            filename: 文件名
            content: 文件内容
            binary: 是否以二进制模式写入
        """
        cache_path = os.path.join(JS_CACHE_DIR, filename)
        tmp_path = f"{cache_path}.tmp"
        try:
            cache_dir = os.path.dirname(cache_path)
            if cache_dir:
                os.makedirs(cache_dir, exist_ok=True)
            mode = "wb" if binary else "w"
            encoding = None if binary else "utf-8"
            with open(tmp_path, mode, encoding=encoding) as f:
                f.write(content)
            os.replace(tmp_path, cache_path)
            logging.info(f"[CDN缓存] 已保存缓存文件: {filename}")
            return True
        except Exception as e:
            try:
                if os.path.exists(tmp_path):
                    os.remove(tmp_path)
            except Exception:
                pass
            logging.error(f"[CDN缓存] 保存缓存文件失败: {e}, 文件: {filename}")
            return False

    # Source Map缓存存储
    source_map_storage = {}
    source_map_lock = threading.Lock()

    def _extract_source_map_url(content, asset_url, file_type="js"):
        """
        从资源内容提取 sourceMappingURL 并解析为绝对URL。
        支持JS与CSS；若未提取到且URL后缀可推断，则尝试 URL + '.map'。
        """
        try:
            matches = []
            if file_type == "css":
                # 匹配 /*# sourceMappingURL=xxx */ 或 /*@ sourceMappingURL=xxx */
                matches = re.findall(
                    r"/\*[@#]\s*sourceMappingURL=([^*\s]+)\s*\*/",
                    content or "",
                    flags=re.IGNORECASE,
                )
            else:
                # 匹配 //# sourceMappingURL=xxx 或 //@ sourceMappingURL=xxx
                matches = re.findall(
                    r"//[@#]\s*sourceMappingURL=([^\s]+)", content or "")

            if matches:
                raw_map = matches[-1].strip()
                return urllib.parse.urljoin(asset_url, raw_map), raw_map

            if isinstance(asset_url, str) and (asset_url.endswith(".js") or asset_url.endswith(".css")):
                return asset_url + ".map", None
        except Exception as e:
            logging.warning(f"[CDN缓存] 提取source map URL失败: {e}")
        return None, None

    def _remove_source_map_comment(content, file_type="js"):
        """
        删除资源中的 sourceMappingURL 注释（支持JS/CSS）
        """
        if not isinstance(content, str):
            return content
        if file_type == "css":
            return re.sub(
                r"\n?/\*[@#]\s*sourceMappingURL=[^*]*\*/\s*$",
                "",
                content,
                flags=re.MULTILINE | re.IGNORECASE,
            )
        return re.sub(
            r"\n?//[@#]\s*sourceMappingURL=[^\n\r]*\s*$",
            "",
            content,
            flags=re.MULTILINE,
        )

    def _safe_delete_cached_file(filename):
        """
        安全删除缓存文件
        """
        try:
            cache_path = os.path.join(JS_CACHE_DIR, filename)
            if os.path.exists(cache_path):
                os.remove(cache_path)
        except Exception as e:
            logging.warning(f"[CDN缓存] 删除缓存文件失败: {filename}, 错误: {e}")

    def process_asset_with_source_map(content, asset_url, key, file_type="js"):
        """
        处理资源中的 sourceMappingURL（支持JS/CSS）。
        - map下载成功：缓存map并改写为本地 /api/cdn/map/<key>
        - map下载失败：清理旧map并删除 sourceMappingURL
        """
        map_url, original_map_ref = _extract_source_map_url(content, asset_url, file_type=file_type)
        if not map_url:
            return content

        map_content = fetch_cdn_file(map_url)
        map_filename = f"{key}.map"

        if map_content:
            # 先写入map缓存，再改写JS
            if save_cached_file(map_filename, map_content):
                with source_map_lock:
                    source_map_storage[key] = map_content
                local_map_ref = f"/api/cdn/map/{key}"
                if original_map_ref:
                    if file_type == "css":
                        content = re.sub(
                            r"/\*[@#]\s*sourceMappingURL=[^*]*\*/\s*$",
                            f"/*# sourceMappingURL={local_map_ref} */",
                            content,
                            flags=re.MULTILINE | re.IGNORECASE,
                        )
                    else:
                        content = re.sub(
                            r"//[@#]\s*sourceMappingURL=[^\n\r]*\s*$",
                            f"//# sourceMappingURL={local_map_ref}",
                            content,
                            flags=re.MULTILINE,
                        )
                else:
                    if file_type == "css":
                        content = content.rstrip() + \
                            f"\n/*# sourceMappingURL={local_map_ref} */\n"
                    else:
                        content = content.rstrip() + \
                            f"\n//# sourceMappingURL={local_map_ref}\n"
                logging.info(f"[CDN缓存] {file_type} source map下载并改写成功: {key}")
            else:
                # map文件保存失败，按失败处理：清理旧map并删除sourceMappingURL
                with source_map_lock:
                    source_map_storage.pop(key, None)
                _safe_delete_cached_file(map_filename)
                content = _remove_source_map_comment(content, file_type=file_type)
                logging.warning(f"[CDN缓存] {file_type} source map保存失败，已移除映射: {key}")
        else:
            # map下载失败：清理旧map并移除JS中的sourceMappingURL
            with source_map_lock:
                source_map_storage.pop(key, None)
            _safe_delete_cached_file(map_filename)
            content = _remove_source_map_comment(content, file_type=file_type)
            logging.warning(f"[CDN缓存] {file_type} source map下载失败，已移除映射: {key}")

        return content

    def update_single_cdn_file(key, config):
        """
        更新单个CDN文件的缓存（先下载并处理，再原子替换）
        """
        url = config["url"]
        filename = config["filename"]
        file_type = config.get("type", "js")

        logging.info(f"[CDN缓存] 正在获取: {key} ({url})")
        content = fetch_cdn_file(url)

        if content:
            # 先处理内容
            if file_type == "css":
                logging.info(f"[CDN缓存] 正在解析CSS中的字体并缓存: {key}")
                content = cache_google_fonts_with_ttf(content, key, url, filename)
                content = process_asset_with_source_map(content, url, key, file_type="css")
            elif file_type == "js":
                content = process_asset_with_source_map(content, url, key, file_type="js")

            # 先落盘，成功后再更新内存缓存，避免更新中断导致文件缺失
            if save_cached_file(filename, content):
                with js_cache_lock:
                    js_cache_storage[key] = content
                    js_cache_last_update[key] = time.time()
                logging.info(f"[CDN缓存] 成功更新: {key}")
                return True
            logging.error(f"[CDN缓存] 保存文件失败: {key}")
            return False

        # 获取失败，尝试使用本地缓存
        cached = load_cached_file(filename)
        if cached:
            with js_cache_lock:
                if key not in js_cache_storage:
                    js_cache_storage[key] = cached
            logging.warning(f"[CDN缓存] 获取失败，使用本地缓存: {key}")
            return False
        logging.error(f"[CDN缓存] 获取失败且无本地缓存: {key}")
        return False

    def update_all_cdn_files():
        """
        更新所有CDN文件的缓存
        """
        logging.info("[CDN缓存] 开始更新所有CDN文件...")
        success_count = 0
        fail_count = 0

        for key, config in CDN_FILES.items():
            if update_single_cdn_file(key, config):
                success_count += 1
            else:
                fail_count += 1

        logging.info(f"[CDN缓存] 更新完成: 成功 {success_count}, 失败 {fail_count}")
        return success_count, fail_count

    def init_cdn_cache():
        """
        初始化CDN缓存：先尝试加载本地缓存，如果没有则从CDN获取
        """
        logging.info("[CDN缓存] 正在初始化CDN文件缓存...")

        # 先加载缓存的字体文件
        load_cached_fonts()

        for key, config in CDN_FILES.items():
            filename = config["filename"]
            # 先尝试加载本地缓存
            cached = load_cached_file(filename)
            if cached:
                with js_cache_lock:
                    js_cache_storage[key] = cached
                    js_cache_last_update[key] = os.path.getmtime(
                        os.path.join(JS_CACHE_DIR, filename)
                    )
                logging.info(f"[CDN缓存] 从本地加载: {key}")
                if config.get("type") in ["js", "css"]:
                    map_filename = f"{key}.map"
                    map_cached = load_cached_file(map_filename)
                    if map_cached:
                        with source_map_lock:
                            source_map_storage[key] = map_cached
                        logging.info(f"[CDN缓存] 从本地加载source map: {key}")
            else:
                # 本地没有缓存，从CDN获取
                update_single_cdn_file(key, config)

        logging.info(
            f"[CDN缓存] 初始化完成，已缓存 {len(js_cache_storage)} 个JS/CSS文件, "
            f"{len(source_map_storage)} 个source map文件, {len(font_cache_storage)} 个字体文件"
        )

    
    _midnight_runtime_reload_hook = init_cdn_cache

    def cdn_cache_update_worker():
        """
        CDN缓存定时更新工作线程（每小时检查一次）
        """
        current_thread = threading.current_thread()
        logging.info(f"[CDN Worker] 已在线程中启动: Thread[{current_thread.name}, id={current_thread.ident}]")
        logging.warning("[Eventlet 警告] CDN worker 运行在独立线程中 - 避免使用 eventlet 操作")
        UPDATE_INTERVAL = 3600  # 1小时

        while True:
            try:
                time.sleep(UPDATE_INTERVAL)
                logging.info("[CDN缓存] 定时更新任务开始...")
                update_all_cdn_files()
            except Exception as e:
                logging.error(f"[CDN缓存] 定时更新任务异常: {e}")

    # 初始化CDN缓存
    init_cdn_cache()

    # 启动CDN缓存定时更新线程
    cdn_update_thread = threading.Thread(
        target=cdn_cache_update_worker, daemon=True, name="CDN_Update_Worker")
    current_thread = threading.current_thread()
    logging.info(f"[线程创建] 正在从 Thread[{current_thread.name}, id={current_thread.ident}] 创建 CDN 更新线程")
    logging.warning("[Eventlet 警告] CDN 更新线程在 eventlet.monkey_patch 之后创建 - 可能导致 greenlet 冲突")
    cdn_update_thread.start()
    logging.info(f"[CDN缓存] 定时更新线程已启动: {cdn_update_thread.name} (id={cdn_update_thread.ident})（每小时检查一次）")

    # ===== 登录验证装饰器 =====
    def login_required(f):
        """
        一个装饰器，用于验证用户是否已登录。
        它检查 X-Session-ID，验证会话，并将用户信息存储在 g 对象中。
        """

        @functools.wraps(f)
        def decorated_function(*args, **kwargs):
            session_id = _main().normalize_session_uuid(_main().request.headers.get("X-Session-ID", ""))
            admin_origin_session_id = _main().normalize_session_uuid(
                _main().request.headers.get(_main().ADMIN_ORIGIN_SESSION_HEADER, "")
            )
            token = _main().request.cookies.get("auth_token")
            admin_origin_context = _main().resolve_admin_origin_session_context(
                session_id,
                admin_origin_session_id,
                token,
            )
            if admin_origin_context:
                _main().g.user = admin_origin_context["username"]
                _main().g.api_instance = admin_origin_context["api_instance"]
                _main().g.session_id = admin_origin_context["session_id"]
                _main().g.viewed_session_id = session_id
                return f(*args, **kwargs)

            api_instance = None
            is_authenticated = False
            auth_username = None
            if session_id:
                with web_sessions_lock:
                    if session_id in web_sessions:
                        api_instance = web_sessions[session_id]
                        is_authenticated = getattr(
                            api_instance, "is_authenticated", False
                        )
                        auth_username = getattr(
                            api_instance, "auth_username", None)
            if not is_authenticated or not api_instance or not auth_username:
                return _main().jsonify({"success": False, "message": "未登录或会话无效"}), 401
            if auth_username != "guest" and not _main()._is_safe_auth_username(
                auth_username
            ):
                return _main().jsonify({"success": False, "message": "用户名格式无效"}), 401
            god_mode_admin = ""
            if not _main()._verify_session_cookie_token(
                session_id,
                auth_username,
                token,
            ):
                # 命名路由的管理员查看态兜底：管理员强制进入他人会话后，老版 UI
                # 只有部分请求携带 X-Admin-Origin-Session-ID（上面的来源会话分支）。
                # 未携带时按 cookie token 反查调用者身份，具备 view_all_sessions
                # 就按查看态放行；否则 /api/check_overdue 这类命名路由会直接 401。
                # 注意：能进入他人会话的不一定是超级管理员。
                view_identity = _main().resolve_admin_view_identity(
                    session_id,
                    token,
                    auth_username,
                )
                if not view_identity:
                    return (
                        _main().jsonify(
                            {
                                "success": False,
                                "message": "认证令牌无效，请重新登录",
                                "need_login": True,
                            }
                        ),
                        401,
                    )
                god_mode_admin = view_identity["username"]
                if not _main()._is_safe_auth_username(god_mode_admin):
                    return _main().jsonify({"success": False, "message": "用户名格式无效"}), 401
                # 业务身份切换为已验证的查看者；业务 API 仍作用在目标会话实例上。
                auth_username = god_mode_admin
                # 标记"查看态但没有来源会话头"：手工校验 token 的命名路由
                # （例如 /auth/admin/all_sessions）必须识别这种情况，否则会拿
                # 被查看会话的 owner 去校验查看者的 token 并返回 401 + 清除 cookie。
                _main().g.admin_view_without_origin = True
                _main().g.viewed_session_id = session_id
            if not god_mode_admin and getattr(api_instance, "is_guest", False):
                return _main().jsonify({"success": False, "message": "游客无权访问此功能"}), 403

            # 账号注销等待期到期后执行惰性删除
            try:
                cancellation_status = _main().auth_system.get_account_cancellation_status(auth_username)
                if (
                    cancellation_status
                    and cancellation_status.get("status") == "pending"
                    and int(cancellation_status.get("execute_at", 0) or 0) <= int(time.time())
                ):
                    _main().auth_system.delete_user(auth_username)
                    # 账号已注销：token 必须显式吊销，不能依赖会话清理里的
                    # "token 仍在使用/还有其他会话"判定。
                    try:
                        _main().token_manager.invalidate_token(auth_username)
                    except Exception as token_error:
                        logging.warning(
                            f"[账号注销] 吊销 token 失败: {token_error}"
                        )
                    # 查看态下 session_id 是"被别人查看的会话"，注销的是查看者
                    # 自己，绝不能销毁被查看用户的会话。
                    if not god_mode_admin:
                        _main().cleanup_session(
                            session_id,
                            reason="account_cancelled",
                        )
                    else:
                        logging.info(
                            "[账号注销] 查看态请求：仅吊销查看者 %s 的 token，"
                            "不销毁被查看会话 %s",
                            auth_username,
                            session_id[:8],
                        )
                    return _main().jsonify({"success": False, "message": "账号已注销"}), 403
            except Exception as _e:
                logging.warning(f"[账号注销] 惰性处理失败: {_e}")

            _main().g.user = auth_username
            _main().g.api_instance = api_instance
            # 将 session_id 存储到 g 对象中，以便被装饰的函数可以访问它（用于审计日志等）
            _main().g.session_id = session_id
            return f(*args, **kwargs)

        return decorated_function

    # ==================== [修正] 添加缺失的 admin_required 装饰器，并采用权限组判断 ====================
    def admin_required(f):
        """
        管理员权限验证装饰器 (基于权限组)
        要求用户已登录，且权限组为 'admin' 或 'super_admin'
        """

        @functools.wraps(f)
        def decorated_function(*args, **kwargs):
            session_id = _main().normalize_session_uuid(
                _main().request.headers.get("X-Session-ID", "")
            )
            api_instance = None
            is_authenticated = False
            auth_username = None
            auth_group = "guest"  # 默认访客组

            # 1. 验证会话和登录状态
            if session_id:
                with web_sessions_lock:
                    if session_id in web_sessions:
                        api_instance = web_sessions[session_id]
                        is_authenticated = getattr(
                            api_instance, "is_authenticated", False
                        )
                        auth_username = getattr(
                            api_instance, "auth_username", None)
                        # 获取权限组（用于后续的组判断）
                        auth_group = getattr(
                            api_instance, "auth_group", "guest")

            if not is_authenticated or not api_instance or not auth_username:
                logging.warning(
                    f"Admin Required Failed: No valid session or not authenticated. Session ID: {session_id[:8]}..."
                )
                return _main().jsonify({"success": False, "message": "未登录或会话无效"}), 401
            if not _main()._is_safe_auth_username(auth_username):
                return _main().jsonify({"success": False, "message": "用户名格式无效"}), 401
            token = _main().request.cookies.get("auth_token")
            god_mode_admin = ""
            if not _main()._verify_session_cookie_token(
                session_id,
                auth_username,
                token,
            ):
                # 与 login_required 一致：管理员查看态下按 cookie token 反查调用者
                # 身份，具备 view_all_sessions 就放行；再用其真实用户组过管理员组
                # 检查（查看他人会话的不一定是超级管理员）。
                view_identity = _main().resolve_admin_view_identity(
                    session_id,
                    token,
                    auth_username,
                )
                if not view_identity:
                    return (
                        _main().jsonify(
                            {
                                "success": False,
                                "message": "认证令牌无效，请重新登录",
                                "need_login": True,
                            }
                        ),
                        401,
                    )
                god_mode_admin = view_identity["username"]
                if not _main()._is_safe_auth_username(god_mode_admin):
                    return _main().jsonify({"success": False, "message": "用户名格式无效"}), 401
                auth_username = god_mode_admin
                auth_group = str(view_identity.get("group") or "user")
                # 与 login_required 一致：标记"查看态但没有来源会话头"。
                _main().g.admin_view_without_origin = True
                _main().g.viewed_session_id = session_id

            # 2. 验证管理员权限 (检查权限组)
            ADMIN_GROUPS = ["admin", "super_admin"]
            if auth_group not in ADMIN_GROUPS:
                logging.warning(
                    f"Admin Required Failed: User {auth_username} (Group: {auth_group}) attempted to access admin route."
                )
                return _main().jsonify({"success": False, "message": "权限不足，仅管理员可访问"}), 403

            # 3. 设置上下文变量
            _main().g.user = auth_username
            _main().g.api_instance = api_instance
            # 将 session_id 存储到 g 对象中，以便被装饰的函数可以访问它（用于审计日志等）
            _main().g.session_id = session_id
            return f(*args, **kwargs)

        return decorated_function
    # ==============================================================================

    def _purge_user_credentials(
        target_username,
        reason,
        extra_sessions=None,
        keep_session_id="",
        clear_stored_session_list=False,
    ):
        """立即作废某个用户的凭证并清理其会话。

        用于“删除用户 / 重置密码 / 修改密码 / 强制销毁会话”这类必须立刻让
        旧 cookie 失效的路径。顺序固定：

            1. 吊销 token（TokenManager 是每用户一个 token，反查索引会同步清理）；
            2. 收集该用户全部会话：内存中的 + 用户文件登记的 + 调用方补充的；
            3. 逐个走统一会话销毁逻辑 cleanup_session()（禁止只删除 web_sessions）；
            4. 按需清空用户文件里的 session_ids。

        Args:
            target_username: 目标用户
            reason: 传给 cleanup_session 的清理原因
            extra_sessions: 调用方额外提供的会话 ID（例如用户文件删除前先取出的）
            keep_session_id: 保留在线的会话（改密后给当前页面重新签发 token 时用）
            clear_stored_session_list: 是否清空用户文件的 session_ids

        Returns:
            int: 实际清理的会话数量
        """
        cleaned_count = 0
        target_username = str(target_username or "").strip()
        if not target_username:
            return cleaned_count

        keep_session_id = _main().normalize_session_uuid(keep_session_id)

        token_invalidated = False
        try:
            _main().token_manager.invalidate_token(target_username)
            token_invalidated = True
        except Exception as error:
            logging.warning(
                "[凭证作废] 吊销 token 失败: user=%s, error=%s",
                target_username,
                error,
            )

        sessions_to_kill = []
        with web_sessions_lock:
            for sid, api in list(web_sessions.items()):
                if getattr(api, "auth_username", "") == target_username:
                    sessions_to_kill.append(sid)

        for sid in list(extra_sessions or []):
            if sid and sid not in sessions_to_kill:
                sessions_to_kill.append(sid)

        try:
            for sid in _main().auth_system.get_user_sessions(target_username) or []:
                if sid and sid not in sessions_to_kill:
                    sessions_to_kill.append(sid)
        except Exception as error:
            logging.warning(
                "[凭证作废] 读取用户会话列表失败: user=%s, error=%s",
                target_username,
                error,
            )

        kept_session = ""
        for sid in sessions_to_kill:
            if keep_session_id and sid == keep_session_id:
                kept_session = sid
                continue
            try:
                _main().cleanup_session(sid, reason=reason)
                cleaned_count += 1
            except Exception as error:
                logging.error(
                    "[凭证作废] 清理会话失败: session=%s, error=%s",
                    sid,
                    error,
                    exc_info=True,
                )

        if clear_stored_session_list:
            try:
                user_file = _main().auth_system.get_user_file_path(target_username)
                if os.path.exists(user_file):
                    with _main().auth_system.lock:
                        with open(user_file, "r", encoding="utf-8") as f:
                            user_data = json.load(f)

                        user_data["session_ids"] = []

                        with open(user_file, "w", encoding="utf-8") as f:
                            json.dump(user_data, f, indent=2, ensure_ascii=False)
            except Exception as error:
                logging.error(
                    "[凭证作废] 清空用户会话列表失败: user=%s, error=%s",
                    target_username,
                    error,
                )

        logging.info(
            "[凭证作废] user=%s, reason=%s, token_invalidated=%s, "
            "cleaned_sessions=%d, kept_session=%s",
            target_username,
            reason,
            token_invalidated,
            cleaned_count,
            kept_session[:8] if kept_session else "-",
        )
        return cleaned_count

    def _resolve_logout_target_sessions(requested_session_id):
        """解析“退出应用/登出”应该销毁的会话。

        管理员查看态（上帝模式、或 /auth/switch_session 切到他人会话）下，
        X-Session-ID 指向的是**被查看的会话**；退出应用只能销毁调用者自己的
        会话（老版查看态的来源会话就是管理员本来的会话），绝不能连带销毁
        被查看用户的会话。

        判定方式：cookie 里的 token 是"每用户一个"，用 token 反查持有者，
        与请求会话的持有者比较：

            - 两者相同（或无法反查）→ 普通登出，销毁请求会话本身；
            - 两者不同 → 查看态，销毁持有者自己的来源会话（请求头来源会话
              优先，其次 session_id Cookie，再退化为该持有者的其他活跃会话）。

        Returns:
            (sessions_to_destroy, caller_username, is_guest_session)
        """
        requested_session_id = _main().normalize_session_uuid(requested_session_id)
        requested_owner = ""
        requested_is_guest = False

        with web_sessions_lock:
            if requested_session_id and requested_session_id in web_sessions:
                requested_api = web_sessions[requested_session_id]
                requested_owner = str(
                    getattr(requested_api, "auth_username", "") or ""
                ).strip()
                requested_is_guest = bool(getattr(requested_api, "is_guest", True))

        if requested_is_guest:
            return (
                [requested_session_id] if requested_session_id else [],
                requested_owner,
                True,
            )

        cookie_token = _main().request.cookies.get("auth_token")
        token_owner = ""
        reverse_lookup = getattr(
            _main().token_manager, "resolve_username_by_token", None
        )
        if callable(reverse_lookup) and cookie_token:
            try:
                resolved = reverse_lookup(cookie_token)
                if isinstance(resolved, str):
                    token_owner = resolved.strip()
            except Exception as error:
                logging.warning("[用户登出] 反查 token 持有者失败: %s", error)

        if (
            not requested_session_id
            or not token_owner
            or token_owner == requested_owner
        ):
            return (
                [requested_session_id] if requested_session_id else [],
                requested_owner or token_owner,
                False,
            )

        # 查看态：只清理调用者自己的会话。
        candidates = []
        origin_header_id = _main().normalize_session_uuid(
            _main().request.headers.get(_main().ADMIN_ORIGIN_SESSION_HEADER, "")
        )
        if origin_header_id:
            candidates.append(origin_header_id)
        cookie_session_id = _main().normalize_session_uuid(
            _main().request.cookies.get("session_id", "")
        )
        if cookie_session_id and cookie_session_id not in candidates:
            candidates.append(cookie_session_id)

        with web_sessions_lock:
            live_sessions = list(web_sessions.items())
        for sid, api_instance in live_sessions:
            if not sid or sid in candidates or sid == requested_session_id:
                continue
            if getattr(api_instance, "auth_username", "") == token_owner:
                candidates.append(sid)

        verified_targets = []
        for sid in candidates:
            if sid == requested_session_id:
                # 被查看的会话永远不在这里销毁。
                continue
            with web_sessions_lock:
                api_instance = web_sessions.get(sid)
            if api_instance is None:
                continue
            if getattr(api_instance, "is_guest", True):
                continue
            if getattr(api_instance, "auth_username", "") != token_owner:
                continue
            if not _main()._verify_session_cookie_token(sid, token_owner, cookie_token):
                continue
            if sid not in verified_targets:
                verified_targets.append(sid)

        if not verified_targets:
            logging.warning(
                "[用户登出] 查看态下未找到调用者 %s 自己的会话，"
                "仅清理请求会话之外的残留状态: viewed=%s",
                token_owner,
                requested_session_id[:8] if requested_session_id else "-",
            )

        return verified_targets, token_owner, False

