    @app.route("/auth/admin/update_group", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def auth_admin_update_group():
        """更新权限组（支持group_key和group_name参数）"""
        # 从Flask的g对象中获取当前登录的用户名和API实例
        auth_username = _main().g.user
        api_instance = _main().g.api_instance

        # 检查细粒度权限：修改权限组权限
        # modify_permission_groups 权限允许修改现有权限组的权限配置
        # 这是敏感操作，通常只有超级管理员才具备此权限
        if not _main().auth_system.check_permission(auth_username, "modify_permission_groups"):
            return _main().jsonify({"success": False, "message": "权限不足，需要修改权限组权限（modify_permission_groups）"}), 403

        data = _main().request.get_json() or {}
        group_name = data.get("group_key") or data.get("group_name", "")
        permissions = data.get("permissions", {})

        # 安全检查：不允许修改超级管理员组
        # 保护系统最高权限组不被修改
        if group_name == "super_admin":
            return _main().jsonify({"success": False, "message": "不允许修改超级管理员组"})

        # 参数验证：权限组标识不能为空
        if not group_name:
            return _main().jsonify({"success": False, "message": "权限组标识不能为空"})
        result = _main().auth_system.update_permission_group(group_name, permissions)
        if not result.get("success", False):
            if "不存在" in result.get("message", ""):
                return _main().jsonify(
                    {"success": False, "message": f"权限组 '{group_name}' 不存在"}
                )

        return _main().jsonify(result)

