    @app.route("/auth/admin/get_user_permissions", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def auth_admin_get_user_permissions():
        """管理员：获取用户的完整权限列表"""
        # 从Flask的g对象中获取当前登录的用户名
        auth_username = _main().g.user

        # 检查细粒度权限：权限管理权限
        # manage_permissions 权限允许查看用户的权限配置
        if not _main().auth_system.check_permission(auth_username, "manage_permissions"):
            return _main().jsonify({"success": False, "message": "权限不足，需要权限管理权限（manage_permissions）"}), 403

        data = _main().request.get_json() or {}
        target_username = data.get("username", "")

        user_current_permissions = _main().auth_system.get_user_permissions(
            target_username)

        all_possible_keys = set()
        super_admin_perms = (
            _main().auth_system.permissions["permission_groups"]
            .get("super_admin", {})
            .get("permissions", {})
        )
        all_possible_keys.update(super_admin_perms.keys())
        for g_data in _main().auth_system.permissions["permission_groups"].values():
            all_possible_keys.update(g_data.get("permissions", {}).keys())

        all_permissions = {}
        for key in all_possible_keys:
            all_permissions[key] = user_current_permissions.get(key, False)

        group = _main().auth_system.get_user_group(target_username)
        group_permissions = (
            _main().auth_system.permissions["permission_groups"]
            .get(group, {})
            .get("permissions", {})
        )
        user_custom = _main().auth_system.permissions.get("user_custom_permissions", {}).get(
            target_username, {}
        )
        added_list = user_custom.get("added", [])
        removed_list = user_custom.get("removed", [])
        added_permissions = {perm: True for perm in added_list}
        removed_permissions = {perm: True for perm in removed_list}

        return _main().jsonify(
            {
                "success": True,
                "group": group,
                "all_permissions": all_permissions,
                "group_permissions": group_permissions,
                "added_permissions": added_permissions,
                "removed_permissions": removed_permissions,
            }
        )

    @app.route("/auth/admin/set_user_permission", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def auth_admin_set_user_permission():
        """管理员：为用户设置自定义权限（差分化存储）"""
        # 从Flask的g对象中获取当前登录的用户名
        auth_username = _main().g.user
        session_id = _main().g.session_id

        # 检查细粒度权限：权限管理权限
        # manage_permissions 权限允许为用户设置自定义权限
        if not _main().auth_system.check_permission(auth_username, "manage_permissions"):
            return _main().jsonify({"success": False, "message": "权限不足，需要权限管理权限（manage_permissions）"}), 403

        data = _main().request.get_json() or {}
        target_username = data.get("username", "")
        added_permissions = data.get("added_permissions", {})
        removed_permissions = data.get("removed_permissions", {})

        if _main().auth_system.get_user_group(_main().g.user) != "super_admin":
            if _main().auth_system.get_user_group(target_username) in ["super_admin", "admin"]:
                return _main().jsonify({"success": False, "message": "管理员只能为普通用户设置自定义权限，无法修改管理员用户的权限"})

        if added_permissions or removed_permissions:
            try:
                if "user_custom_permissions" not in _main().auth_system.permissions:
                    _main().auth_system.permissions["user_custom_permissions"] = {}

                _main().auth_system.permissions["user_custom_permissions"][target_username] = {
                    "added": list(added_permissions.keys()),
                    "removed": list(removed_permissions.keys()),
                }

                _main().auth_system._save_permissions()
                # 使用统一函数获取客户端真实IP
                ip_address = _main().request.environ.get(
                    "REMOTE_ADDR") or _main().request.remote_addr
                _main().auth_system.log_audit(
                    auth_username,
                    "set_user_permissions_batch",
                    f"批量更新用户 {target_username} 的差分权限: 添加{len(added_permissions)}个, 移除{len(removed_permissions)}个",
                    ip_address,
                    _main().g.session_id,
                )

                return _main().jsonify({"success": True, "message": "权限已更新"})
            except Exception as e:
                logging.error(f"批量更新权限失败: {e}", exc_info=True)
                return (
                    _main().jsonify({"success": False, "message": f"更新失败: {str(e)}"}),
                    500,
                )
        else:
            permission = data.get("permission", "")
            grant = data.get("grant", False)

            if not permission:
                logging.info(
                    f"管理员 {auth_username} 尝试为用户 {target_username} 设置权限时，缺少 permission 参数"
                )
                try:
                    if "user_custom_permissions" not in _main().auth_system.permissions:
                        _main().auth_system.permissions["user_custom_permissions"] = {}

                    _main().auth_system.permissions["user_custom_permissions"][
                        target_username
                    ] = {"added": [], "removed": []}

                    _main().auth_system._save_permissions()

                    # 使用统一函数获取客户端真实IP
                    ip_address = _main().request.environ.get(
                        "REMOTE_ADDR") or _main().request.remote_addr
                    _main().auth_system.log_audit(
                        auth_username,
                        "set_user_permissions_batch",
                        f"批量更新用户 {target_username} 的差分权限: 清空用户的差分权限",
                        ip_address,
                        _main().g.session_id,
                    )

                    return _main().jsonify({"success": True, "message": "权限已更新"})
                except Exception as e:
                    logging.error(f"批量更新权限失败: {e}", exc_info=True)
                    return (
                        _main().jsonify(
                            {"success": False, "message": f"更新失败: {str(e)}"}),
                        500,
                    )

            result = _main().auth_system.set_user_custom_permission(
                target_username, permission, grant
            )

            # 使用统一函数获取客户端真实IP
            ip_address = _main().request.environ.get(
                "REMOTE_ADDR") or _main().request.remote_addr
            _main().auth_system.log_audit(
                auth_username,
                "set_user_permission",
                f'为用户 {target_username} {"授予" if grant else "移除"} 权限: {permission}',
                ip_address,
                _main().g.session_id,
            )

            return _main().jsonify(result)

    @app.route("/auth/get_config", methods=["GET"])
    def auth_get_config():
        """
        获取认证配置（用于前端显示）
        使用 _get_config_value 辅助函数安全地读取配置，避免 ValueError 崩溃
        """
        allow_guest_login = _get_config_value(
            _main().auth_system.config,
            "Guest",
            "allow_guest_login",
            type_func=lambda x: str(x).lower() in ("true", "yes", "1", "on"),
            fallback=True,
        )
        guest_config = _main()._get_guest_config(_main().auth_system.config)
        active_guest_sessions = _main()._count_active_guest_sessions(
            guest_config["guest_session_inactivity_timeout"]
        )
        max_active_guest_sessions = guest_config["max_active_guest_sessions"]
        return _main().jsonify(
            {
                "success": True,
                "allow_guest_login": allow_guest_login,
                "max_active_guest_sessions": max_active_guest_sessions,
                "active_guest_sessions": active_guest_sessions,
                "guest_capacity_available": (
                    active_guest_sessions < max_active_guest_sessions
                ),
            }
        )

    @app.route("/auth/check_uuid_type", methods=["POST"])
    def auth_check_uuid_type():
        """
        检查UUID类型：游客UUID、系统账号UUID或未知UUID
        用于实现访问控制和会话验证
        """
        data = _main().request.json
        check_uuid = data.get("uuid", "")

        if not check_uuid:
            return _main().jsonify({"success": False, "message": "UUID参数缺失"}), 400
        uuid_pattern = re.compile(
            r"^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$",
            re.IGNORECASE,
        )
        if not uuid_pattern.match(check_uuid):
            return (
                _main().jsonify(
                    {
                        "success": False,
                        "message": "无效的UUID格式，请使用标准UUID v4格式",
                    }
                ),
                400,
            )
        session_file = _main().get_session_file_path(check_uuid)
        file_exists = os.path.exists(session_file)
        logging.debug(
            # f"/auth/check_uuid_type: Checking UUID {check_uuid[:8]}..., File path: {session_file}, Exists: {file_exists}"
            f"正在检查UUID {check_uuid[:8]}...，文件路径: {session_file}，存在: {file_exists}"
        )

        if not file_exists:
            return _main().jsonify(
                {
                    "success": True,
                    "uuid_type": "unknown",
                    "message": "UUID不存在",
                }
            )
        max_retries = 3
        retry_delay = 0.1
        fcntl = None

        for attempt in range(max_retries):
            try:
                with open(session_file, "r", encoding="utf-8") as f:
                    if fcntl:
                        fcntl.flock(f.fileno(), fcntl.LOCK_SH)
                    try:
                        session_data = json.load(f)
                    finally:
                        if fcntl:
                            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
                is_guest = session_data.get("is_guest", False)
                auth_username = session_data.get("auth_username", "")

                if is_guest or auth_username == "guest":
                    return _main().jsonify(
                        {
                            "success": True,
                            "uuid_type": "guest",
                            "message": "游客UUID",
                            "theme_background": _main()._resolve_uuid_theme_background(
                                check_uuid, "guest", True
                            ),
                        }
                    )
                elif auth_username:
                    return _main().jsonify(
                        {
                            "success": True,
                            "uuid_type": "system_account",
                            "auth_username": auth_username,
                            "message": "系统账号UUID",
                            "theme_background": _main()._resolve_uuid_theme_background(
                                check_uuid, auth_username, False
                            ),
                        }
                    )
                else:
                    logging.warning(
                        f"/auth/check_uuid_type: 文件 {session_file} 存在但内容无法识别用户类型 (auth_username='{auth_username}', is_guest={is_guest})，返回 unknown"
                    )
                    return _main().jsonify(
                        {
                            "success": True,
                            "uuid_type": "unknown",
                            "message": "未知类型UUID (内容无法识别)",
                        }
                    )
            except (IOError, OSError) as e:
                if attempt < max_retries - 1:

                    time.sleep(retry_delay)
                    continue
                else:
                    logging.error(f"读取会话文件失败（已重试{max_retries}次）: {e}")
                    return (
                        _main().jsonify(
                            {"success": False, "message": "读取会话失败，请稍后重试"}
                        ),
                        500,
                    )
            except json.JSONDecodeError as e:
                logging.error(f"会话文件JSON解析失败: {e}")
                return _main().jsonify({"success": False, "message": "会话数据损坏"}), 500
            except Exception as e:
                logging.error(f"检查UUID类型失败: {e}")
                return (
                    _main().jsonify({"success": False, "message": f"服务器错误: {str(e)}"}),
                    500,
                )

    @app.route("/auth/2fa/generate", methods=["POST"])
    def auth_2fa_generate():
        """生成2FA密钥"""
        session_id = _main().request.headers.get("X-Session-ID", "")
        if not session_id or session_id not in web_sessions:
            return _main().jsonify({"success": False, "message": "未登录"}), 401

        api_instance = web_sessions[session_id]
        if not getattr(api_instance, "is_authenticated", False):
            return _main().jsonify({"success": False, "message": "未认证"}), 401

        auth_username = getattr(api_instance, "auth_username", "")
        if auth_username == "guest":
            return _main().jsonify({"success": False, "message": "游客不支持2FA"}), 403

        result = _main().auth_system.generate_2fa_secret(auth_username)
        return _main().jsonify(result)

    @app.route("/auth/2fa/enable", methods=["POST"])
    def auth_2fa_enable():
        """启用2FA"""
        data = _main().request.get_json() or {}
        verification_code = data.get("code", "").strip()
        session_id = _main().request.headers.get("X-Session-ID", "")

        if not session_id or session_id not in web_sessions:
            return _main().jsonify({"success": False, "message": "未登录"}), 401

        api_instance = web_sessions[session_id]
        if not getattr(api_instance, "is_authenticated", False):
            return _main().jsonify({"success": False, "message": "未认证"}), 401

        auth_username = getattr(api_instance, "auth_username", "")
        result = _main().auth_system.enable_2fa(auth_username, verification_code)
        return _main().jsonify(result)

    @app.route("/auth/2fa/verify", methods=["POST"])
    def auth_2fa_verify():
        """测试验证2FA代码（用于用户测试2FA是否工作正常）"""
        data = _main().request.get_json() or {}
        verification_code = data.get("code", "").strip()
        session_id = _main().request.headers.get("X-Session-ID", "")

        if not session_id or session_id not in web_sessions:
            return _main().jsonify({"success": False, "message": "未登录"}), 401

        api_instance = web_sessions[session_id]
        if not getattr(api_instance, "is_authenticated", False):
            return _main().jsonify({"success": False, "message": "未认证"}), 401

        auth_username = getattr(api_instance, "auth_username", "")
        if auth_username == "guest":
            return _main().jsonify({"success": False, "message": "游客不支持2FA"}), 403
        if _main().auth_system.verify_2fa(auth_username, verification_code):
            return _main().jsonify({"success": True, "message": "验证码正确"})
        else:
            return _main().jsonify({"success": False, "message": "验证码错误"})

    @app.route("/auth/2fa/disable", methods=["POST"])
    def auth_2fa_disable():
        """关闭2FA"""
        session_id = _main().request.headers.get("X-Session-ID", "")

        if not session_id or session_id not in web_sessions:
            return _main().jsonify({"success": False, "message": "未登录"}), 401

        api_instance = web_sessions[session_id]
        if not getattr(api_instance, "is_authenticated", False):
            return _main().jsonify({"success": False, "message": "未认证"}), 401

        auth_username = getattr(api_instance, "auth_username", "")
        if auth_username == "guest":
            return _main().jsonify({"success": False, "message": "游客不支持2FA"}), 403
        user_file = _main().auth_system.get_user_file_path(auth_username)
        if os.path.exists(user_file):
            try:
                with _main().auth_system.lock:
                    with open(user_file, "r", encoding="utf-8") as f:
                        user_data = json.load(f)

                    user_data["2fa_enabled"] = False
                    with open(user_file, "w", encoding="utf-8") as f:
                        json.dump(user_data, f, indent=2, ensure_ascii=False)

                logging.info(f"用户 {auth_username} 已关闭2FA")
                return _main().jsonify({"success": True, "message": "2FA已关闭"})
            except Exception as e:
                logging.error(f"关闭2FA失败: {e}", exc_info=True)
                return (
                    _main().jsonify({"success": False, "message": f"关闭失败: {str(e)}"}),
                    500,
                )
        else:
            return _main().jsonify({"success": False, "message": "用户不存在"}), 404

    @app.route("/auth/2fa/verify_login", methods=["POST"])
    def auth_2fa_verify_login():
        """验证2FA代码并完成登录（用于登录流程中的2FA验证）"""
        data = _main().request.get_json() or {}
        auth_username = data.get("auth_username", "").strip()
        verification_code = data.get("code", "").strip()
        challenge_token = str(
            data.get("challenge") or data.get("two_fa_challenge") or ""
        ).strip()

        if not auth_username:
            return _main().jsonify({"success": False, "message": "缺少用户名"}), 400

        if not verification_code:
            return _main().jsonify({"success": False, "message": "缺少验证码"}), 400
        if not challenge_token:
            return _main().jsonify({"success": False, "message": "缺少2FA challenge"}), 400

        challenge_valid, challenge_error = _main()._consume_two_fa_challenge(
            challenge_token,
            auth_username,
            verification_code,
            _main().auth_system.verify_2fa,
        )
        if not challenge_valid:
            logging.warning(f"2FA登录验证失败: {auth_username}")
            return _main().jsonify({"success": False, "message": challenge_error}), 401
        requested_session_id = _main().normalize_session_uuid(
            _main().request.headers.get("X-Session-ID", "")
        )
        api_instance = None
        session_is_persistent = False
        if requested_session_id:
            with web_sessions_lock:
                if requested_session_id in web_sessions:
                    api_instance = web_sessions[requested_session_id]
                    session_is_persistent = getattr(
                        api_instance, "_is_persistent_session", True
                    )
                else:
                    state = _main().load_session_state(requested_session_id)
                    if state:
                        api_instance = _main().Api(args)
                        api_instance._session_created_at = state.get(
                            "created_at", time.time()
                        )
                        api_instance._web_session_id = requested_session_id
                        api_instance._is_persistent_session = True
                        _main().restore_session_to_api_instance(api_instance, state)
                        web_sessions[requested_session_id] = api_instance
                        session_is_persistent = True

        session_id = requested_session_id if api_instance else str(uuid.uuid4())
        if api_instance is None:
            api_instance = _main().Api(args)
            api_instance._session_created_at = time.time()
            api_instance._web_session_id = session_id
            api_instance._is_persistent_session = False
        else:
            api_instance._web_session_id = session_id
        api_instance.is_authenticated = True
        api_instance.auth_username = auth_username
        user_group = _main().auth_system.get_user_group(auth_username)
        api_instance.auth_group = user_group
        is_guest = auth_username == "guest"
        api_instance.is_guest = is_guest
        web_sessions[session_id] = api_instance
        user_file = _main().auth_system.get_user_file_path(auth_username)
        if os.path.exists(user_file):
            try:
                with _main().auth_system.lock:
                    with open(user_file, "r", encoding="utf-8") as f:
                        user_data = json.load(f)

                    user_data["last_login"] = time.time()
                    with open(user_file, "w", encoding="utf-8") as f:
                        json.dump(user_data, f, indent=2, ensure_ascii=False)
            except Exception as e:
                logging.error(f"更新用户登录信息失败: {e}", exc_info=True)
        token = None
        if not is_guest:
            try:
                token = _main().token_manager.create_token(auth_username, session_id)
                _main().token_manager.cleanup_expired_tokens(auth_username)
            except Exception as e:
                logging.error(f"Token管理过程出错: {e}")
                token = None

        logging.info(f"用户 {auth_username} 通过2FA验证登录成功")

        response_data = {
            "success": True,
            "message": "2FA验证成功",
            "session_id": session_id if session_is_persistent else None,
            "auth_session_id": session_id,
            "is_guest": is_guest,
            "token": token,
        }
        response = _main().jsonify(response_data)
        if token:
            response.set_cookie(
                "auth_token",
                value=token,
                max_age=3600,  # 1小时
                httponly=True,
                secure=False,
                samesite="Lax",
            )

        return response

    @app.route("/auth/admin/create_user", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def auth_admin_create_user():
        """管理员：创建新用户

        请求参数：
        - username: 用户名（必填）
        - password: 密码（必填）
        - group: 用户组（可选，默认 user）
        - phone: 手机号（可选）
        - nickname: 昵称（可选）
        - sms_code: 短信验证码（可选，如非空则进行校验）

        available_runs（可用次数）处理：
        - 本API不需要在请求参数中指定 available_runs
        - 新用户的 available_runs 将自动从 config.ini 的 [Payment_Settings] -> default_available_runs 读取
        - 这确保了所有创建用户的方式（PC端、移动端、自助注册）都使用统一的默认值
        - 如需修改某个用户的 available_runs，请在用户创建后通过用户管理功能进行修改
        """
        # 从Flask的g对象中获取当前登录的用户名
        auth_username = _main().g.user
        # 从Flask的g对象中获取会话ID（由 @login_required 装饰器设置），用于审计日志记录
        session_id = _main().g.session_id

        # 检查细粒度权限：管理用户权限
        # manage_users 权限允许创建新用户账号
        if not _main().auth_system.check_permission(auth_username, "manage_users"):
            return _main().jsonify({"success": False, "message": "权限不足，需要用户管理权限（manage_users）"}), 403

        data = _main().request.json
        new_username = data.get("username", "")
        password = data.get("password", "")
        group = data.get("group", "user")
        phone = data.get("phone", "").strip()
        nickname = data.get("nickname", "").strip()
        sms_code = data.get("sms_code", "").strip()

        if not new_username or not password:
            return _main().jsonify({"success": False, "message": "用户名和密码不能为空"})
        if not _main()._is_safe_auth_username(new_username):
            return (
                _main().jsonify(
                    {
                        "success": False,
                        "message": "用户名包含非法字符，只允许字母、数字、下划线、连字符、点和@符号",
                    }
                ),
                400,
            )

        # 如果填写了手机号，验证格式
        if phone:
            # import re

            if not re.match(r"^1[3-9]\d{9}$", phone):
                return _main().jsonify({"success": False, "message": "手机号格式不正确"})

        # 如果填写了验证码，进行校验（验证码非空时必须校验）
        if sms_code and phone:
            # 调用短信验证码校验逻辑
            if hasattr(_main().auth_system, "sms_codes") and phone in _main().auth_system.sms_codes:
                stored = _main().auth_system.sms_codes[phone]
                # import time

                if stored.get("code") != sms_code:
                    return _main().jsonify({"success": False, "message": "短信验证码错误"})
                if time.time() > stored.get("expire_at", 0):
                    return _main().jsonify({"success": False, "message": "短信验证码已过期"})
                # 验证成功，删除已使用的验证码
                del _main().auth_system.sms_codes[phone]
            else:
                return _main().jsonify({"success": False, "message": "短信验证码不存在或已过期"})

        result = _main().auth_system.register_user(new_username, password, group)
        if result.get("success"):
            # 使用统一函数获取客户端真实IP
            ip_address = _main().request.environ.get(
                "REMOTE_ADDR") or _main().request.remote_addr

            # 如果提供了手机号，绑定到新用户
            if phone:
                try:
                    _main().auth_system.update_user_phone(new_username, phone)
                except Exception as e:
                    print(f"[警告] 绑定手机号失败: {e}")

            # 如果提供了昵称，更新昵称
            if nickname:
                try:
                    _main().auth_system.update_user_nickname(new_username, nickname)
                except Exception as e:
                    print(f"[警告] 更新昵称失败: {e}")

            _main().auth_system.log_audit(
                auth_username,
                "create_user",
                f"创建新用户: {new_username} (组: {group})"
                + (f", 手机: {phone}" if phone else ""),
                ip_address,
                session_id,
            )

        return _main().jsonify(result)

