    @app.route("/logs/view", methods=["GET"])
    def view_logs():
        """查看应用日志（管理员）- 分页模式"""
        session_id = _main().request.headers.get("X-Session-ID", "")
        if not session_id or session_id not in web_sessions:
            return _main().jsonify({"success": False, "message": "未登录"}), 401

        api_instance = web_sessions[session_id]
        auth_group = getattr(api_instance, "auth_group", "guest")
        if auth_group not in ["admin", "super_admin"]:
            return _main().jsonify({"success": False, "message": "权限不足"}), 403
        # --- 分页参数 ---
        try:
            page = int(_main().request.args.get("page", 1))
            limit = int(_main().request.args.get("limit", 100))
            if page < 1:
                page = 1
            if limit < 1:
                limit = 100
            if limit > 2000:
                limit = 2000
        except ValueError:
            page = 1
            limit = 100

        keyword_expr = _main().request.args.get("keyword", "").strip()
        log_keyword_or_operator = chr(124)
        log_keyword_and_operator = chr(38)
        log_keyword_operators = {log_keyword_or_operator, log_keyword_and_operator}

        def normalize_log_keyword_expr(expr):
            return re.sub(r"\s+", "", expr or "")

        def tokenize_log_keyword_expr(expr):
            normalized = normalize_log_keyword_expr(expr)
            if not normalized:
                return []
            tokens = []
            current = []
            for ch in normalized:
                if ch in log_keyword_operators:
                    if current:
                        tokens.append("".join(current))
                        current = []
                    tokens.append(ch)
                else:
                    current.append(ch)
            if current:
                tokens.append("".join(current))
            return [token for token in tokens if token]

        def matches_log_keyword_expr(line, expr):
            tokens = tokenize_log_keyword_expr(expr)
            if not tokens:
                return True

            line_lower = line.lower()
            or_groups = []
            current_group = []

            for token in tokens:
                if token == log_keyword_or_operator:
                    if current_group:
                        or_groups.append(current_group)
                        current_group = []
                    continue
                if token == log_keyword_and_operator:
                    continue
                current_group.append(token.lower())

            if current_group:
                or_groups.append(current_group)

            if not or_groups:
                return True

            return any(
                all(keyword and keyword in line_lower for keyword in group)
                for group in or_groups
            )

        all_log_content = []
        log_files = []
        if os.path.exists(_main().LOGIN_LOGS_DIR):
            files = sorted(
                [
                    f
                    for f in os.listdir(_main().LOGIN_LOGS_DIR)
                    if f.endswith(".log") or f.endswith(".jsonl")
                ]
            )
            for f in files:
                log_files.append(os.path.join(_main().LOGIN_LOGS_DIR, f))
        for log_file in log_files:
            try:
                with open(log_file, "r", encoding="utf-8") as f:
                    all_log_content.extend(f.readlines())
            except (FileNotFoundError, PermissionError, UnicodeDecodeError) as e:
                logging.debug(f"[日志读取] 无法读取日志文件 {log_file}: {e}")
                continue

        if keyword_expr:
            all_log_content = [
                line for line in all_log_content if matches_log_keyword_expr(line, keyword_expr)
            ]

        total_lines = len(all_log_content)
        total_pages = (total_lines + limit - 1) // limit
        if page > total_pages and total_pages > 0:
            page = total_pages
        start_index = max(0, total_lines - (page * limit))
        end_index = total_lines - ((page - 1) * limit)
        paginated_logs = all_log_content[start_index:end_index]
        paginated_logs.reverse()

        return _main().jsonify(
            {
                "success": True,
                "logs": paginated_logs,
                "pagination": {
                    "current_page": page,
                    "total_pages": total_pages,
                    "total_lines": total_lines,
                    "limit": limit,
                },
                "filters": {"keyword": keyword_expr},
            }
        )

    @app.route("/auth/admin/reset_password", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def auth_admin_reset_password():
        """
        重置用户密码（管理员）或修改自己的密码。

        支持两种身份验证方式：
        1. 原密码验证（old_password参数）
        2. 短信验证码验证（sms_code参数）

        修改自己密码时，至少需要提供其中一种验证方式。
        管理员重置他人密码时，需要拥有reset_user_password权限。
        """
        global sms_verification_codes
        # 从Flask的g对象中获取当前登录的用户名和用户组
        auth_username = _main().g.user
        api_instance = _main().g.api_instance
        auth_group = getattr(api_instance, "auth_group", "guest")

        # 解析请求体JSON数据
        data = _main().request.json
        # 获取目标用户名（要重置密码的用户）
        target_username = data.get("username", "")
        # 获取新密码
        new_password = data.get("new_password", "")
        # 获取旧密码（用于原密码验证方式）
        old_password = data.get("old_password", "")
        # 新增：获取短信验证码参数（用于短信验证码验证方式）
        sms_code = data.get("sms_code", "")

        # 验证必填参数：目标用户名和新密码
        if not target_username or not new_password:
            return _main().jsonify({"success": False, "message": "参数缺失"})

        # 检查新密码强度
        # 在允许密码重置之前，检查新密码是否为弱密码
        # 这可以防止用户设置不安全的密码，提高账户安全性
        is_weak, weak_reason = _main().is_weak_password(new_password)
        if is_weak:
            # 如果新密码过弱，返回错误信息，要求用户设置更强的密码
            return _main().jsonify({"success": False, "message": f"新密码强度不足：{weak_reason}"}), 400

        # 判断是否是修改自己的密码
        is_self_change = target_username == auth_username

        if is_self_change:
            # ========== 修改自己的密码，需要验证身份 ==========
            # 支持两种验证方式：原密码 或 短信验证码
            # 至少需要提供其中一种验证方式
            # 注意：如果同时提供了两种验证方式，优先使用短信验证码
            if not old_password and not sms_code:
                return _main().jsonify(
                    {"success": False, "message": "请提供当前密码或短信验证码"}
                )

            # 获取用户信息文件路径
            user_file = _main().auth_system.get_user_file_path(auth_username)
            # 检查用户文件是否存在
            if not os.path.exists(user_file):
                return _main().jsonify({"success": False, "message": "用户不存在"}), 404

            try:
                # 读取用户信息文件
                with open(user_file, "r", encoding="utf-8") as f:
                    user_data = json.load(f)
                # 获取存储的密码哈希值
                stored_password = user_data.get("password")
                # 获取用户绑定的手机号（用于短信验证）
                user_phone = user_data.get("phone", "")
            except Exception as e:
                # 读取用户信息失败，记录错误日志
                logging.error(f"读取用户 {auth_username} 信息失败: {e}")
                return _main().jsonify({"success": False, "message": "无法验证身份"}), 500

            # ========== 开始身份验证 ==========
            # 用于记录是否使用了短信验证码，以便在密码重置成功后删除验证码
            sms_verified_phone = None

            if sms_code:
                # ===== 方式一：使用短信验证码验证（优先级更高） =====
                # 当同时提供了短信验证码和原密码时，优先使用短信验证码
                # 检查用户是否已绑定手机号
                if not user_phone:
                    return (
                        _main().jsonify(
                            {
                                "success": False,
                                "message": "您未绑定手机号，无法使用短信验证",
                            }
                        ),
                        400,
                    )

                # 声明使用全局的短信验证码存储字典
                
                # 从存储中获取该手机号对应的验证码信息
                stored_code_info = sms_verification_codes.get(user_phone)

                # 检查是否存在该手机号的验证码
                if not stored_code_info:
                    return (
                        _main().jsonify({"success": False, "message": "请先获取短信验证码"}),
                        400,
                    )

                # 解构验证码信息：验证码内容和过期时间
                stored_code, expires_at = stored_code_info

                # 检查验证码是否已过期
                if time.time() > expires_at:
                    # 验证码已过期，删除已过期的验证码
                    del sms_verification_codes[user_phone]
                    return (
                        _main().jsonify(
                            {"success": False, "message": "验证码已过期，请重新获取"}
                        ),
                        400,
                    )

                # 验证输入的验证码是否正确
                if stored_code != sms_code:
                    return _main().jsonify({"success": False, "message": "短信验证码错误"}), 400

                # 记录短信验证成功，但暂不删除验证码
                # 验证码将在密码重置成功后删除，确保操作原子性
                sms_verified_phone = user_phone
                # 记录验证成功日志
                logging.info(f"用户 {auth_username} 使用短信验证码成功验证身份")
            else:
                # ===== 方式二：使用原密码验证 =====
                # 调用密码验证方法，比较输入的旧密码与存储的密码哈希值
                if not _main().auth_system._verify_password(old_password, stored_password):
                    # 密码验证失败
                    return _main().jsonify({"success": False, "message": "当前密码错误"}), 401
        else:
            # ========== 管理员重置他人密码 ==========
            # 检查当前用户是否拥有重置他人密码的权限
            if not _main().auth_system.check_permission(auth_username, "reset_user_password"):
                return _main().jsonify({"success": False, "message": "权限不足"}), 403
            # 管理员重置他人密码不使用短信验证
            sms_verified_phone = None

        # 调用auth_system的方法重置密码
        result = _main().auth_system.reset_user_password(target_username, new_password)

        # 密码重置成功后，删除已使用的短信验证码（如果使用了短信验证）
        # 放在此处确保只有在密码重置成功后才删除验证码
        # 如果重置失败，验证码仍然有效，用户可以重试
        if sms_verified_phone and result.get("success"):
            if sms_verified_phone in sms_verification_codes:
                del sms_verification_codes[sms_verified_phone]

        if not result.get("success"):
            return _main().jsonify(result)

        # 密码变更后旧 cookie 必须立即失效，不能继续用旧凭证访问。
        current_session_id = _main().normalize_session_uuid(
            getattr(_main().g, "session_id", "")
        )
        refreshed_token = ""
        if is_self_change:
            # 改自己的密码：作废旧 token 并清理其他会话/设备，但保留当前会话，
            # 再为当前会话补发 token 写回 cookie，避免用户改完密码立刻掉线。
            cleaned_count = _purge_user_credentials(
                target_username,
                reason="password_changed",
                keep_session_id=current_session_id,
            )
            if current_session_id:
                try:
                    refreshed_token = _main().token_manager.create_token(
                        target_username, current_session_id
                    )
                except Exception as error:
                    logging.error(
                        f"[密码修改] 为当前会话重新签发 token 失败: {error}"
                    )
            else:
                logging.warning(
                    "[密码修改] 无法解析当前会话 ID，用户需要重新登录"
                )
        else:
            # 管理员重置他人密码：吊销 token 并清理对方全部会话。
            cleaned_count = _purge_user_credentials(
                target_username,
                reason="password_reset",
            )

        result["cleaned_sessions"] = cleaned_count
        response = _main().jsonify(result)
        if refreshed_token:
            response.set_cookie(
                "auth_token",
                value=refreshed_token,
                max_age=3600,
                httponly=True,
                secure=False,
                samesite="Lax",
            )
        return response

    @app.route("/auth/user/request_account_cancellation", methods=["POST"])
    @login_required
    def auth_user_request_account_cancellation():
        """用户申请账号注销（密码+短信验证码双重校验，默认24小时等待期）。"""
        global sms_verification_codes
        auth_username = _main().g.user
        data = _main().request.get_json() or {}
        current_password = (data.get("current_password") or "").strip()
        sms_code = (data.get("sms_code") or "").strip()
        # 优先使用配置文件中的冷静期，允许前端覆盖（取两者中较大值以不低于配置）
        config_wait = _main().auth_system.config.getint("Features", "account_cancellation_wait_hours", fallback=24)
        wait_hours = int(data.get("wait_hours", config_wait) or config_wait)
        wait_hours = max(1, wait_hours)

        if not current_password or not sms_code:
            return _main().jsonify({"success": False, "message": "请提供当前密码和短信验证码"}), 400
        if not re.match(r"^\d{6}$", sms_code):
            return _main().jsonify({"success": False, "message": "短信验证码格式错误"}), 400

        user_file = _main().auth_system.get_user_file_path(auth_username)
        if not os.path.exists(user_file):
            return _main().jsonify({"success": False, "message": "用户不存在"}), 404
        with open(user_file, "r", encoding="utf-8") as f:
            user_data = json.load(f)

        stored_password = user_data.get("password", "")
        user_phone = user_data.get("phone", "")
        if not user_phone:
            return _main().jsonify({"success": False, "message": "未绑定手机号，无法进行短信验证"}), 400
        if not _main().auth_system._verify_password(current_password, stored_password):
            return _main().jsonify({"success": False, "message": "当前密码错误"}), 401

        
        stored_code_info = sms_verification_codes.get(user_phone)
        if not stored_code_info:
            return _main().jsonify({"success": False, "message": "请先获取短信验证码"}), 400
        stored_code, expires_at = stored_code_info
        if time.time() > expires_at:
            del sms_verification_codes[user_phone]
            return _main().jsonify({"success": False, "message": "短信验证码已过期，请重新获取"}), 400
        if stored_code != sms_code:
            return _main().jsonify({"success": False, "message": "短信验证码错误"}), 400

        result = _main().auth_system.set_account_cancellation_pending(auth_username, wait_hours)
        if not result.get("success"):
            return _main().jsonify(result), 400

        if user_phone in sms_verification_codes:
            del sms_verification_codes[user_phone]

        session_id = _main().g.session_id
        ip_address = _main().request.environ.get("REMOTE_ADDR") or _main().request.remote_addr
        _main().auth_system.log_audit(
            auth_username,
            "request_account_cancellation",
            f"申请账号注销，等待期{wait_hours}小时",
            ip_address,
            session_id,
        )

        return _main().jsonify({
            "success": True,
            "message": f"已提交账号注销申请，等待期{wait_hours}小时",
            "status": {
                "status": "pending",
                "execute_at": result.get("execute_at")
            }
        })

    @app.route("/auth/user/cancel_account_cancellation", methods=["POST"])
    @login_required
    def auth_user_cancel_account_cancellation():
        """用户撤销账号注销申请（在等待期内）。"""
        auth_username = _main().g.user
        user_file = _main().auth_system.get_user_file_path(auth_username)
        if not os.path.exists(user_file):
            return _main().jsonify({"success": False, "message": "用户不存在"}), 404
        with _main().auth_system.lock:
            with open(user_file, "r", encoding="utf-8") as f:
                user_data = json.load(f)
            cancellation = user_data.get("account_cancellation")
            if not cancellation or cancellation.get("status") != "pending":
                return _main().jsonify({"success": False, "message": "当前没有待处理的注销申请"})
            user_data["account_cancellation"] = None
            with open(user_file, "w", encoding="utf-8") as f:
                json.dump(user_data, f, indent=2, ensure_ascii=False)
        _main().auth_system.log_audit(
            auth_username,
            "cancel_account_cancellation",
            "用户在等待期内撤销了账号注销申请",
            _main().request.environ.get("REMOTE_ADDR") or _main().request.remote_addr,
            _main().g.session_id,
        )
        return _main().jsonify({"success": True, "message": "账号注销申请已撤销"})


