    @app.route("/auth/user/upload_avatar", methods=["POST"])
    def auth_user_upload_avatar():
        """上传用户头像文件（multipart/form-data）"""

        session_id = _main().request.headers.get("X-Session-ID", "")
        if not session_id or session_id not in web_sessions:
            return _main().jsonify({"success": False, "message": "未登录"}), 401

        api_instance = web_sessions[session_id]
        auth_username = getattr(api_instance, "auth_username", "")

        if not auth_username or auth_username == "guest":
            return _main().jsonify({"success": False, "message": "游客无法上传头像"})
        if "avatar" not in _main().request.files:
            return _main().jsonify({"success": False, "message": "未找到头像文件"}), 400

        file = _main().request.files["avatar"]

        if file.filename == "":
            return _main().jsonify({"success": False, "message": "未选择文件"}), 400
        allowed_extensions = {".png", ".jpg", ".jpeg", ".gif", ".webp"}
        file_ext = os.path.splitext(file.filename)[1].lower()
        if file_ext not in allowed_extensions:
            return (
                _main().jsonify(
                    {"success": False, "message": "不支持的文件格式，请上传图片文件"}
                ),
                400,
            )
        file_content = file.read()
        max_size = 5 * 1024 * 1024
        if len(file_content) > max_size:
            return (
                _main().jsonify({"success": False, "message": "文件过大，请上传小于5MB的图片"}),
                400,
            )

        try:
            img = _main().Image.open(io.BytesIO(file_content))
            if img.mode in ("RGBA", "LA", "P"):
                pass
            elif img.mode != "RGB":
                img = img.convert("RGB")
            png_buffer = io.BytesIO()
            img.save(png_buffer, format="PNG", optimize=True)
            png_content = png_buffer.getvalue()
            sha256_hash = hashlib.sha256(png_content).hexdigest()
            images_dir = os.path.join("system_accounts", "images")
            os.makedirs(images_dir, exist_ok=True)
            filename = f"{sha256_hash}.png"
            filepath = os.path.join(images_dir, filename)

            with open(filepath, "wb") as f:
                f.write(png_content)
            index_file = os.path.join(images_dir, "_index.json")
            try:
                if os.path.exists(index_file):
                    with open(index_file, "r", encoding="utf-8") as f:
                        index_data = json.load(f)
                else:
                    index_data = {
                        "version": "1.0",
                        "description": "用户头像索引文件，记录每个文件的上传信息",
                        "files": {},
                    }
                # 使用统一函数获取客户端真实IP
                ip_address = _main().request.environ.get(
                    "REMOTE_ADDR") or _main().request.remote_addr
                index_data["files"][filename] = {
                    "username": auth_username,
                    "upload_time": time.time(),
                    "upload_time_str": datetime.datetime.now().isoformat(),
                    "ip_address": ip_address,
                    "original_filename": file.filename,
                    "file_size": len(png_content),
                    "sha256": sha256_hash,
                }
                with open(index_file, "w", encoding="utf-8") as f:
                    json.dump(index_data, f, indent=2, ensure_ascii=False)

                logging.info(
                    f"用户 {auth_username} 从 {ip_address} 上传头像: {filename}"
                )
            except Exception as e:
                logging.error(f"更新头像索引失败: {e}", exc_info=True)
        except Exception as e:
            return (
                _main().jsonify({"success": False, "message": f"图片处理失败: {str(e)}"}),
                500,
            )
        avatar_url = f"/api/avatar/{filename}"
        result = _main().auth_system.update_user_avatar(auth_username, avatar_url)

        if result.get("success"):
            return _main().jsonify(
                {"success": True, "avatar_url": avatar_url, "message": "头像上传成功"}
            )
        else:
            try:
                os.remove(filepath)
                if os.path.exists(index_file):
                    with open(index_file, "r", encoding="utf-8") as f:
                        index_data = json.load(f)
                    if filename in index_data.get("files", {}):
                        del index_data["files"][filename]
                        with open(index_file, "w", encoding="utf-8") as f:
                            json.dump(index_data, f, indent=2,
                                      ensure_ascii=False)
            except (OSError, PermissionError) as e:
                logging.warning(f"[会话索引] 更新索引文件失败: {e}")
            return _main().jsonify(result)

    @app.route("/default_avatar.png")
    @app.route("/static/default_avatar.png")
    def serve_default_avatar():
        """
        为 default_avatar.png 提供根路径和 /static 路径的访问。
        """
        try:
            # import os

            base_dir = os.path.dirname(__file__)
            default_avatar_path = os.path.join(base_dir, "default_avatar.png")

            if os.path.exists(default_avatar_path):
                return _main().send_file(default_avatar_path, mimetype="image/png")
            else:
                logging.warning(
                    f"Default avatar not found at {default_avatar_path}")
                return "Default avatar not found", 404
        except NameError as e:
            logging.error(
                f"Serve default avatar failed: {e}. Is send_file imported?")
            return "Server configuration error", 500
        except Exception as e:
            logging.error(f"Error serving default avatar: {e}", exc_info=True)
            return "Server error", 500

    @app.route("/api/avatar/<filename>", methods=["GET"])
    def serve_avatar(filename):
        """提供头像图片服务（需要会话认证，管理员可访问）"""

        if filename == "default_avatar.png":
            return _main().redirect("/default_avatar.png")
        session_id = (
            _main().request.headers.get("X-Session-ID", "")
            or _main().request.cookies.get("session_id", "")
            or _main().request.args.get("session_id", "")
        )
        if not session_id or session_id not in web_sessions:
            return _main().jsonify({"success": False, "message": "未授权访问"}), 401
        api_instance = web_sessions[session_id]
        current_username = getattr(api_instance, "auth_username", "")
        if not _main()._verify_session_cookie_token(
            session_id,
            current_username,
            _main().request.cookies.get("auth_token"),
        ):
            return _main().jsonify({"success": False, "message": "认证令牌无效"}), 401
        is_admin = (
            _main().auth_system.check_permission(current_username, "manage_users")
            if current_username
            else False
        )
        if filename == "default_avatar.png":
            default_avatar_path = os.path.join(
                os.path.dirname(__file__), "default_avatar.png"
            )
            if os.path.exists(default_avatar_path):
                try:
                    return _main().send_file(default_avatar_path, mimetype="image/png")
                except Exception as e:
                    return (
                        _main().jsonify(
                            {"success": False,
                                "message": f"读取默认头像失败: {str(e)}"}
                        ),
                        500,
                    )
            else:
                return _main().jsonify({"success": False, "message": "默认头像文件不存在"}), 404
        if not filename.endswith(".png") or len(filename) != 68:
            return _main().jsonify({"success": False, "message": "无效的文件名"}), 400
        filepath = os.path.join("system_accounts", "images", filename)
        if not os.path.exists(filepath):
            return _main().jsonify({"success": False, "message": "头像不存在"}), 404
        try:
            return _main().send_file(filepath, mimetype="image/png")
        except Exception as e:
            return (
                _main().jsonify({"success": False, "message": f"读取文件失败: {str(e)}"}),
                500,
            )

    @app.route("/auth/admin/clear_user_avatar", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def auth_admin_clear_user_avatar():
        """管理员：强制清除用户头像"""
        # 获取当前登录用户
        # 使用Flask的g对象获取用户名，这是由@login_required装饰器设置的
        auth_username = _main().g.user

        # 检查细粒度权限：用户管理权限
        # manage_users 权限允许管理员执行用户相关的管理操作，包括清除用户头像
        # 这是一个涉及用户数据修改的敏感操作，需要专门的用户管理权限
        if not _main().auth_system.check_permission(auth_username, 'manage_users'):
            return _main().jsonify({
                "success": False,
                "message": "权限不足，需要用户管理权限（manage_users）"
            }), 403
        # 从Flask的g对象中获取会话ID（由 @login_required 装饰器设置），用于审计日志记录
        session_id = _main().g.session_id

        data = _main().request.json
        target_username = data.get("username", "")

        if not target_username:
            return _main().jsonify({"success": False, "message": "缺少用户名参数"}), 400
        user_details = _main().auth_system.get_user_details(target_username)
        if not user_details:
            return _main().jsonify({"success": False, "message": "用户不存在"}), 404

        old_avatar_url = user_details.get("avatar_url", "")
        result = _main().auth_system.update_user_avatar(
            target_username, "default_avatar.png")

        if result.get("success"):
            if old_avatar_url:
                try:
                    filename = old_avatar_url.split("/")[-1]
                    filepath = os.path.join(
                        "system_accounts", "images", filename)
                    index_file = os.path.join(
                        "system_accounts", "images", "_index.json"
                    )
                    if os.path.exists(index_file):
                        with open(index_file, "r", encoding="utf-8") as f:
                            index_data = json.load(f)

                        file_info = index_data.get(
                            "files", {}).get(filename, {})
                        if file_info.get("username") == target_username:
                            if os.path.exists(filepath):
                                os.remove(filepath)
                                logging.info(
                                    f"管理员 {auth_username} 删除了用户 {target_username} 的头像文件: {filename}"
                                )
                            if filename in index_data.get("files", {}):
                                del index_data["files"][filename]
                                with open(index_file, "w", encoding="utf-8") as f:
                                    json.dump(
                                        index_data, f, indent=2, ensure_ascii=False
                                    )
                        else:
                            logging.info(
                                f"管理员 {auth_username} 清除了用户 {target_username} 的头像URL，但文件由其他用户上传，未删除文件"
                            )

                except Exception as e:
                    logging.error(f"清除头像文件时出错: {e}", exc_info=True)
            # 使用统一函数获取客户端真实IP
            ip_address = _main().request.environ.get(
                "REMOTE_ADDR") or _main().request.remote_addr
            _main().auth_system.log_audit(
                auth_username,
                "clear_user_avatar",
                f"强制清除用户 {target_username} 的头像",
                ip_address,
                session_id,
            )

            return _main().jsonify(
                {"success": True, "message": f"已清除用户 {target_username} 的头像"}
            )
        else:
            return _main().jsonify(result)

