    @app.route("/api/admin/logs/login_history", methods=["GET"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def admin_logs_login_history():
        """
        查看用户登录历史记录
        """
        try:
            # 从Flask的g对象中获取当前登录的用户名
            current_user = _main().g.user

            # 细粒度权限检查：需要 'view_audit_logs' 权限
            # view_audit_logs 权限允许查看用户的登录历史记录
            # 这是审计功能的一部分，用于安全监控和合规检查
            if not _main().auth_system.check_permission(current_user, "view_audit_logs"):
                return _main().jsonify({
                    "success": False,
                    "message": "权限不足，需要审计日志查看权限（view_audit_logs）"
                }), 403

            # 获取查询参数
            target_username = _main().request.args.get("username", "").strip()
            limit = int(_main().request.args.get("limit", 100))

            # 确定要查询的用户名
            # 如果没有指定target_username，则查询所有用户的登录历史
            username_to_query = target_username if target_username else None
            history = _main().auth_system.get_login_history(username_to_query, limit)
            history.reverse()

            return _main().jsonify(
                {
                    "success": True,
                    "logs": history,
                    "total": len(history),
                }
            )

        except Exception as e:
            app.logger.error(f"[登录历史] 查询失败：{str(e)}")
            return _main().jsonify({"success": False, "message": "查询失败"}), 500

    @app.route("/api/admin/logs/audit", methods=["GET"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def admin_logs_audit():
        """
        查看用户审计日志（操作记录）
        """

        try:
            # 检查细粒度权限：查看审计日志权限
            # view_audit_logs 权限允许查看系统的操作审计日志
            # 审计日志记录了所有敏感操作，用于安全审计和合规要求
            if not _main().auth_system.check_permission(_main().g.user, "view_audit_logs"):
                return _main().jsonify({"success": False, "message": "权限不足，需要查看审计日志权限（view_audit_logs）"}), 403
            username = _main().request.args.get("username", "").strip()
            action = _main().request.args.get("action", "").strip()
            limit = int(_main().request.args.get("limit", 100))
            logs = _main().auth_system.get_audit_logs(username, action, limit)

            return _main().jsonify({"success": True, "logs": logs, "total": len(logs)})

        except Exception as e:
            app.logger.error(f"[审计日志] 查询失败：{str(e)}")
            return _main().jsonify({"success": False, "message": "查询失败"}), 500

