    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def get_verification_codes():
        """
        获取当前有效的验证码列表
        """
        try:
            # 细粒度权限检查：需要 'view_audit_logs' 权限
            # view_audit_logs 权限允许查看短信验证码列表
            # 验证码是敏感的临时凭证，查看权限需要严格控制
            if not _main().auth_system.check_permission(_main().g.user, "view_audit_logs"):
                return _main().jsonify({
                    "success": False,
                    "message": "权限不足，需要审计日志查看权限（view_audit_logs）"
                }), 403

            # 获取当前时间戳，用于过滤过期验证码
            _main()._cleanup_expired_sms_verification_codes()
            current_time = time.time()
            codes = []
            for phone, (code, expire_time) in list(sms_verification_codes.items()):
                if expire_time > current_time:
                    codes.append(
                        {
                            "phone": phone,
                            "code": code,
                            "expires_at": expire_time,
                            "expires_in": int(expire_time - current_time),
                        }
                    )
            codes.sort(key=lambda x: x["expires_at"])

            return _main().jsonify({"success": True, "codes": codes})
        except Exception as e:
            app.logger.error(f"[验证码管理] 获取列表失败：{str(e)}")
            return _main().jsonify({"success": False, "message": "获取列表失败"}), 500

    @app.route("/api/admin/sms/invalidate_code", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def invalidate_verification_code():
        """
        使指定手机号的验证码失效
        """
        try:
            # 细粒度权限检查：需要 'manage_system' 权限
            # manage_system 权限允许管理短信验证码的生命周期
            # 使验证码失效可能影响用户的注册或验证流程
            if not _main().auth_system.check_permission(_main().g.user, "manage_system"):
                return _main().jsonify({
                    "success": False,
                    "message": "权限不足，需要系统管理权限（manage_system）"
                }), 403

            # 获取请求数据
            data = _main().request.get_json() or {}
            phone = data.get("phone", "").strip()

            if not phone:
                return _main().jsonify({"success": False, "message": "手机号不能为空"})
            if phone in sms_verification_codes:
                del sms_verification_codes[phone]
                app.logger.info(f"[验证码管理] {g.user} 使 {phone} 的验证码失效")
                _emit_verification_codes_update(_main().g.api_instance._web_session_id)
                return _main().jsonify({"success": True, "message": "验证码已失效"})
            else:
                return _main().jsonify({"success": False, "message": "未找到该手机号的验证码"})
        except Exception as e:
            app.logger.error(f"[验证码管理] 使验证码失效失败：{str(e)}")
            return _main().jsonify({"success": False, "message": "操作失败"}), 500

    @app.route("/api/sms/extend_code", methods=["POST"])
    def extend_verification_code():
        """
        延长验证码有效期API
        用于在手机号未注册时，延长验证码有效期以便用户跳转到注册页面
        """
        try:
            data = _main().request.get_json() or {}
            phone = data.get("phone", "").strip()
            
            if not phone or not re.match(r"^1[3-9]\d{9}$", phone):
                return _main().jsonify({"success": False, "message": "手机号格式不正确"})
            
            # 检查该手机号是否有有效的验证码
            if phone not in sms_verification_codes:
                return _main().jsonify({"success": False, "message": "该手机号没有待验证的验证码"})
            
            code, expire_time = sms_verification_codes[phone]
            current_time = time.time()

            # 检查验证码是否已过期
            if current_time > expire_time:
                del sms_verification_codes[phone]
                _main()._reset_sms_extend_once_for_phone(phone)
                return _main().jsonify({"success": False, "message": "验证码已过期"})

            if not _main()._is_sms_extend_allowed_once(phone, code):
                remaining_seconds = max(0, int(expire_time - current_time))
                return _main().jsonify(
                    {
                        "success": False,
                        "error_code": "EXTEND_LIMIT_REACHED",
                        "message": "该验证码已延期过一次，请直接完成注册",
                        "expires_at": int(expire_time),
                        "remaining_seconds": remaining_seconds,
                    }
                )

            # 延长验证码有效期（额外增加5分钟）
            extend_minutes = 5
            extend_seconds = extend_minutes * 60
            new_expire_time = current_time + extend_seconds

            _main()._cleanup_expired_sms_verification_codes(now_ts=current_time)
            sms_verification_codes[phone] = (code, new_expire_time)
            _main()._mark_sms_extend_used_once(phone, code)

            app.logger.info(
                f"[验证码延长] 手机号 {phone} 的验证码有效期已延长 {extend_minutes} 分钟"
            )

            return _main().jsonify(
                {
                    "success": True,
                    "message": f"验证码有效期已延长{extend_minutes}分钟",
                    "extend_minutes": extend_minutes,
                    "expires_at": int(new_expire_time),
                    "remaining_seconds": int(extend_seconds),
                }
            )
            
        except Exception as e:
            app.logger.error(f"[验证码延长] 延长失败：{str(e)}")
            return _main().jsonify({"success": False, "message": "延长失败"}), 500

    @app.route("/api/admin/sms/add_manual_code", methods=["POST"])
    @login_required  # 只需要登录即可，细粒度权限在函数内部检查
    def add_manual_verification_code():
        """
        手动添加验证码（模拟发送，用于测试或紧急情况）
        """
        try:
            # 细粒度权限检查：需要 'manage_system' 权限
            # manage_system 权限允许手动添加短信验证码
            # 这是用于测试或紧急情况的特殊操作，需要严格控制
            if not _main().auth_system.check_permission(_main().g.user, "manage_system"):
                return _main().jsonify({
                    "success": False,
                    "message": "权限不足，需要系统管理权限（manage_system）"
                }), 403

            # 获取请求数据
            data = _main().request.get_json() or {}
            phone = data.get("phone", "").strip()
            code = data.get("code", "").strip()
            if not phone or not re.match(r"^1[3-9]\d{9}$", phone):
                return _main().jsonify({"success": False, "message": "手机号格式不正确"})
            if not code or not re.match(r"^\d{6}$", code):
                return _main().jsonify({"success": False, "message": "验证码必须是6位数字"})
            config = configparser.ConfigParser(strict=False)
            config = _main()._read_config_ini(_main().CONFIG_JSON_FILE) or _main()._get_default_config()
            code_expire_minutes = int(
                config.get("SMS_Service_SMSBao",
                           "code_expire_minutes", fallback="5")
            )
            code_expire_seconds = code_expire_minutes * 60
            current_ts = time.time()
            expire_time = current_ts + code_expire_seconds
            _main()._cleanup_expired_sms_verification_codes(now_ts=current_ts)
            sms_verification_codes[phone] = (code, expire_time)
            _main()._reset_sms_extend_once_for_phone(phone)

            app.logger.info(
                f"[验证码管理] {g.user} 手动添加验证码: {phone} (有效期{code_expire_minutes}分钟)"
            )

            try:

                log_dir = _main().LOGIN_LOGS_DIR
                os.makedirs(log_dir, exist_ok=True)

                session_id = (
                    _main().g.api_instance._web_session_id
                    if hasattr(_main().g, "api_instance")
                    else None
                )
                # 使用统一函数获取客户端真实IP
                client_ip = _main().request.environ.get(
                    "REMOTE_ADDR") or _main().request.remote_addr
                content = f"管理员 {g.user} 手动添加的验证码: {code}，{code_expire_minutes}分钟内有效。"

                history_entry = {
                    "session_id": session_id,
                    "username": _main().g.user,
                    "phone": phone,
                    "scene": "admin_manual_add",
                    "timestamp": time.time(),
                    "datetime": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "content": content,
                    "ip": client_ip,
                }

                history_file = os.path.join(log_dir, "sms_history.jsonl")
                with open(history_file, "a", encoding="utf-8") as f:
                    f.write(json.dumps(history_entry, ensure_ascii=False) + "\n")

                app.logger.debug(
                    f"[短信历史] 已记录手动添加验证码: {phone} -> {g.user}"
                )
            except Exception as e:
                app.logger.error(f"[短信历史] 记录手动添加验证码失败: {str(e)}")
            _emit_verification_codes_update(_main().g.api_instance._web_session_id)

            return _main().jsonify(
                {
                    "success": True,
                    "message": f"验证码已添加，{code_expire_minutes}分钟内有效",
                }
            )
        except Exception as e:
            app.logger.error(f"[验证码管理] 添加验证码失败：{str(e)}")
            return _main().jsonify({"success": False, "message": "添加失败"}), 500

