    @app.route("/api/frontend-config")
    def api_frontend_config():
        """
        返回前端需要的配置信息（JSON格式）
        用于客户端动态加载配置，减轻服务器端渲染压力
        """
        try:
            session_id = _main().normalize_session_uuid(
                _main().request.headers.get("X-Session-ID", "")
            )
            username = None
            if session_id:
                with web_sessions_lock:
                    api_instance = web_sessions.get(session_id)
                    if api_instance is not None and not getattr(
                        api_instance, "is_guest", True
                    ):
                        username = getattr(api_instance, "auth_username", None)
            config = get_frontend_config(session_id=session_id, username=username)
            return _main()._apply_no_cache_headers(_main().jsonify(config))
        except Exception as e:
            logging.error(f"获取前端配置失败: {e}")
            # 使用集中定义的默认配置
            return _main()._apply_no_cache_headers(_main().jsonify(DEFAULT_FRONTEND_CONFIG)), 500

    # ========== 新增路由：CDN缓存文件API ==========
    @app.route("/api/cdn/<file_key>")
    def get_cdn_cached_file(file_key):
        """
        返回本地缓存的CDN文件（JS/CSS）

        参数:
            file_key: 文件标识符，如 sweetalert2, qrcode, cropperjs, cropperjs-css

        返回:
            文件内容，并设置正确的Content-Type
        """
        # 直接忽略所有 source map 请求（浏览器调试工具发出的 .map 请求）
        if file_key.endswith(".map"):
            return _main().make_response("", 204)
        try:
            with js_cache_lock:
                if file_key in js_cache_storage:
                    content = js_cache_storage[file_key]
                    file_config = CDN_FILES.get(file_key, {})
                    file_type = file_config.get("type", "js")

                    # 设置正确的Content-Type
                    if file_type == "css":
                        mimetype = "text/css"
                    else:
                        mimetype = "application/javascript"

                    if file_type == "js":
                        return _main()._make_frontend_javascript_response(
                            content,
                            cache_control="public, max-age=3600",
                        )

                    response = _main().make_response(content)
                    response.headers["Content-Type"] = mimetype
                    response.headers["Cache-Control"] = (
                        "public, max-age=3600"  # 缓存1小时
                    )
                    return response
                else:
                    logging.warning(f"[CDN缓存API] 请求的文件不存在: {file_key}")
                    return (
                        _main().jsonify(
                            {"success": False, "message": f"文件未找到: {file_key}"}
                        ),
                        404,
                    )
        except Exception as e:
            logging.error(f"[CDN缓存API] 返回文件时发生错误: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": "服务器内部错误"}), 500

