    @app.route("/api/cdn/font/<font_key>")
    def get_cdn_cached_font(font_key):
        """
        返回本地缓存的字体文件（TTF/WOFF/WOFF2/OTF）

        参数:
            font_key: 字体文件标识符，如 notosanssc-xxx.ttf

        返回:
            字体文件内容，并设置正确的Content-Type
        """
        try:
            with font_cache_lock:
                if font_key in font_cache_storage:
                    content = font_cache_storage[font_key]

                    # 根据文件扩展名设置正确的Content-Type
                    if font_key.endswith(".woff2"):
                        mimetype = "font/woff2"
                    elif font_key.endswith(".woff"):
                        mimetype = "font/woff"
                    elif font_key.endswith(".ttf"):
                        mimetype = "font/ttf"
                    elif font_key.endswith(".otf"):
                        mimetype = "font/otf"
                    else:
                        mimetype = "application/octet-stream"

                    response = _main().make_response(content)
                    response.headers["Content-Type"] = mimetype
                    response.headers["Cache-Control"] = (
                        "public, max-age=31536000"  # 缓存1年（字体文件很少变化）
                    )
                    response.headers["Access-Control-Allow-Origin"] = (
                        "*"  # 允许跨域访问字体
                    )
                    return response
                else:
                    logging.warning(f"[CDN缓存API] 请求的字体文件不存在: {font_key}")
                    return (
                        _main().jsonify(
                            {"success": False, "message": f"字体文件未找到: {font_key}"}
                        ),
                        404,
                    )
        except Exception as e:
            logging.error(f"[CDN缓存API] 返回字体文件时发生错误: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": "服务器内部错误"}), 500

    @app.route("/api/cdn/refresh", methods=["POST"])
    @admin_required
    @login_required
    def refresh_cdn_cache():
        """
        手动刷新CDN缓存（管理员功能）
        """
        try:
            session_id = _main().request.headers.get("X-Session-ID", "")
            if not session_id:
                return _main().jsonify({"success": False, "message": "未授权"}), 401

            # 检查是否有管理员权限
            api_instance = None
            with web_sessions_lock:
                if session_id in web_sessions:
                    api_instance = web_sessions[session_id]

            if not api_instance:
                return _main().jsonify({"success": False, "message": "会话无效"}), 401

            auth_username = getattr(api_instance, "auth_username", None)
            if not auth_username:
                return _main().jsonify({"success": False, "message": "未登录"}), 401

            # 检查管理员权限
            if not _main().auth_system.check_permission(auth_username, "modify_config"):
                return _main().jsonify({"success": False, "message": "权限不足"}), 403

            # 执行刷新
            success_count, fail_count = update_all_cdn_files()

            return _main().jsonify(
                {
                    "success": True,
                    "message": f"CDN缓存刷新完成: 成功 {success_count}, 失败 {fail_count}",
                    "success_count": success_count,
                    "fail_count": fail_count,
                }
            )
        except Exception as e:
            logging.error(f"[CDN缓存API] 刷新缓存时发生错误: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": "服务器内部错误"}), 500

