    @app.route("/api/captcha/detail/<captcha_id>", methods=["GET"])
    @login_required
    def get_captcha_detail(captcha_id):
        """
        获取单个验证码的详细信息

        权限要求：管理员 (view_captcha_history)
        """
        try:
            if not _main().auth_system.check_permission(_main().g.user, "view_captcha_history"):
                return _main().jsonify({"success": False, "message": "权限不足"}), 403
            if not captcha_id or ".." in captcha_id or "/" in captcha_id:
                return _main().jsonify({"success": False, "message": "无效的验证码ID"}), 400
            history_dir = os.path.join(_main().LOGIN_LOGS_DIR, "captcha_history")
            if not os.path.exists(history_dir):
                return (
                    _main().jsonify({"success": False, "message": "验证码历史目录不存在"}),
                    404,
                )

            found_record = None
            current_time = time.time()
            expiry_threshold = 30 * 60
            for filename in os.listdir(history_dir):
                if filename.endswith(".jsonl"):
                    history_file = os.path.join(history_dir, filename)
                    try:
                        with open(history_file, "r", encoding="utf-8") as f:
                            for line in f:
                                try:
                                    record = json.loads(line.strip())
                                    if record.get("captcha_id") == captcha_id:
                                        found_record = record
                                        if record.get("status") == "created":
                                            timestamp = record.get(
                                                "timestamp", 0)
                                            if (
                                                current_time - timestamp
                                                > expiry_threshold
                                            ):
                                                found_record["status"] = "expired"
                                                found_record["expired_at"] = (
                                                    timestamp + expiry_threshold
                                                )
                                                found_record["expired_at_readable"] = (
                                                    datetime.datetime.fromtimestamp(
                                                        timestamp + expiry_threshold
                                                    ).strftime("%Y-%m-%d %H:%M:%S")
                                                )
                                        found_record.pop("session_id", None)
                                        _main().normalize_captcha_history_record(found_record)
                                        return _main().jsonify(
                                            {"success": True, "data": found_record}
                                        )
                                except json.JSONDecodeError:
                                    continue
                    except (IOError, OSError) as e:
                        logging.warning(
                            f"[验证码详情] 读取历史文件 {filename} 失败: {e}"
                        )
                        continue
            if not found_record:
                return (
                    _main().jsonify({"success": False, "message": "未找到该验证码的详细信息"}),
                    404,
                )

        except Exception as e:
            logging.error(f"[验证码详情] 获取详情失败: {e}", exc_info=True)
            return (
                _main().jsonify({"success": False, "message": "获取验证码详情时发生错误"}),
                500,
            )

