    @app.route("/api/captcha/save_settings", methods=["POST"])
    @login_required
    def save_captcha_settings():
        """
        【本地验证码】保存验证码生成器设置到config.ini
        """
        try:
            # ========================================
            # 1. 权限检查：只有管理员可以修改验证码设置
            # ========================================
            if not _main().auth_system.check_permission(_main().g.user, "modify_config"):
                logging.warning(
                    f"【本地验证码】用户 {g.user} 尝试保存验证码设置但权限不足"
                )
                return (
                    _main().jsonify(
                        {
                            "success": False,
                            "message": "权限不足：只有管理员可以修改验证码设置",
                        }
                    ),
                    403,
                )
            # ========================================
            # 2. 解析请求数据
            # ========================================
            data = _main().request.get_json()
            if not data:
                return _main().jsonify({"success": False, "message": "请求数据为空"}), 400
            # ========================================
            # 3. 提取并验证参数
            # ========================================
            try:
                length = int(data.get("length", 4))
                scale_factor = int(data.get("scale_factor", 2))
                noise_level = float(data.get("noise_level", 0.08))
            except (ValueError, TypeError) as e:
                logging.error(f"【本地验证码】参数类型转换失败: {e}")
                return (
                    _main().jsonify({"success": False, "message": f"参数类型错误: {str(e)}"}),
                    400,
                )
            if not (3 <= length <= 6):
                return (
                    _main().jsonify({"success": False, "message": "验证码长度必须在3-6之间"}),
                    400,
                )

            if not (2 <= scale_factor <= 32):
                return (
                    _main().jsonify({"success": False, "message": "细分倍数必须在2-32之间"}),
                    400,
                )

            if not (0 <= noise_level <= 0.3):
                return (
                    _main().jsonify({"success": False, "message": "噪点比例必须在0.0-0.3之间"}),
                    400,
                )

            logging.info(
                f"【本地验证码】用户 {g.user} 请求保存验证码设置: length={length}, scale_factor={scale_factor}, noise_level={noise_level}"
            )
            # ========================================
            # 4. 读取现有配置文件
            # ========================================
            config_file = _main().CONFIG_JSON_FILE
            config = _main()._read_config_ini(config_file) or _main()._get_default_config()
            # ========================================
            # 5. 确保[Captcha]节存在
            # ========================================
            if not config.has_section("Captcha"):
                config.add_section("Captcha")
                logging.debug("【本地验证码】[Captcha]节不存在，已创建")

            # ========================================
            # 6. 更新配置值
            # ========================================
            config.set("Captcha", "length", str(length))
            config.set("Captcha", "scale_factor", str(scale_factor))
            config.set("Captcha", "noise_level", str(noise_level))

            # ========================================
            # 6.1 验证码提供方配置（本地图片 / 本地行为验证码）
            #     仅当请求携带对应字段时更新，保持向后兼容
            # ========================================
            if "provider" in data:
                _provider = str(data.get("provider") or "image").strip().lower()
                if _provider not in ("image", "behavior"):
                    _provider = "image"
                config.set("Captcha", "provider", _provider)
            if "behavior_base_url" in data:
                config.set("Captcha", "behavior_base_url",
                           str(data.get("behavior_base_url") or "").strip().rstrip("/"))
            if "behavior_api_key" in data:
                config.set("Captcha", "behavior_api_key",
                           str(data.get("behavior_api_key") or "").strip())
            if "behavior_type" in data:
                config.set("Captcha", "behavior_type",
                           (str(data.get("behavior_type") or "SLIDER").strip() or "SLIDER"))

            _main()._write_config_with_comments(config, config_file)

            logging.info(f"【本地验证码】验证码设置已成功保存到 {config_file}")
            # ========================================
            # 8. 返回成功响应
            # ========================================
            return _main().jsonify({"success": True, "message": "验证码设置保存成功"})
        except Exception as e:
            logging.error(f"【本地验证码】保存验证码设置失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"保存失败: {str(e)}"}), 500

