    @app.route("/api/admin/clear_overdue", methods=["POST"])
    @login_required
    @admin_required
    def admin_clear_overdue():
        """
        管理员清除/修改/添加学校账号欠费次数

        功能说明：
        此接口允许管理员直接修改指定用户的指定学校账号的欠费次数。
        支持两种模式：覆盖模式（直接设置为指定值）和叠加模式（在现有次数上累加）。
        主要用于帮助用户结清欠费、纠正错误的欠费记录，或手动添加欠费记录。

        权限要求：管理员（admin或super_admin）
        请求方法：POST

        请求参数（JSON格式）：
        {
            "auth_username": "user123",        // 用户名（账号所属用户，可为空）
            "school_username": "2021001",      // 学校账号用户名（必填）
            "new_overdue_count": 0,            // 欠费次数
            "add_mode": false                  // 叠加模式（true=累加，false=覆盖，默认false）
        }

        返回数据（JSON格式）：
        成功时：
        {
            "success": true,
            "message": "欠费次数已更新为 X"
        }

        失败时：
        {
            "success": false,
            "message": "错误信息描述"
        }

        使用场景：
        1. 用户完成线下支付后，管理员手动清零欠费（add_mode=false, new_overdue_count=0）
        2. 系统误判导致欠费次数错误，管理员纠正数据（add_mode=false）
        3. 管理员手动添加欠费次数（add_mode=true，叠加到已有次数上）

        安全机制：
        1. 必须有管理员权限（@admin_required装饰器）
        2. 参数验证：学校账号不能为空
        3. 参数验证：覆盖模式下欠费次数必须是非负整数；叠加模式下必须大于0
        4. 记录详细的管理员操作日志，便于审计追溯

        ⚠️ 此接口已弃用（Deprecated），请改用 POST /api/admin/billing/add。
        保留此接口仅为向后兼容，后续版本将移除。
        """
        logging.warning(
            "[已弃用] /api/admin/clear_overdue 已弃用，请改用 /api/admin/billing/add"
        )
        try:
            # ========== 步骤1：获取并验证请求参数 ==========

            # 从请求体中获取JSON数据
            # 如果请求体为空或不是JSON格式，使用空字典作为默认值
            data = _main().request.get_json() or {}

            # 从请求数据中提取参数，并去除首尾空白字符
            # auth_username: 目标用户的用户名（认证系统中的用户）

            auth_username = str(data.get("auth_username", "")).strip()

            # school_username: 要操作的学校账号用户名
            school_username = str(data.get("school_username", "")).strip()

            # new_overdue_count: 新的欠费次数，默认为0（清零）
            new_overdue_count = data.get("new_overdue_count", 0)

            # add_mode: 叠加模式。True 表示将 new_overdue_count 累加到现有欠费次数；
            # False（默认）表示直接覆盖为 new_overdue_count。
            add_mode = bool(data.get("add_mode", False))

            # ========== 步骤2：基本参数验证 ==========

            # 验证学校账号不能为空（这是必须的）
            if not school_username:
                return _main().jsonify({
                    "success": False,
                    "message": "学校账号不能为空"
                }), 400

            # 如果auth_username为空，尝试自动查找
            # 这种情况通常发生在管理员只知道school_username的情况下
            if not auth_username:
                try:
                    user_accounts_dir = os.path.join(_main().SCHOOL_ACCOUNTS_DIR, "user_accounts")
                    if os.path.isdir(user_accounts_dir):
                        for fname in os.listdir(user_accounts_dir):
                            if fname.endswith(".json"):
                                try:
                                    with open(os.path.join(user_accounts_dir, fname), 'r', encoding='utf-8') as f:
                                        data = json.load(f)
                                        if school_username in data:
                                            auth_username = fname[:-5] # remove .json
                                            break
                                except Exception:
                                    pass
                except Exception:
                    pass

            # ========== 步骤3：验证欠费次数参数 ==========
            try:
                new_overdue_count = int(new_overdue_count)
                # 叠加模式要求次数大于0；覆盖模式允许0（用于清零）
                if add_mode and new_overdue_count < 1:
                    return _main().jsonify({"success": False, "message": "添加的欠费次数必须大于0"}), 400
                elif not add_mode and new_overdue_count < 0:
                    return _main().jsonify({"success": False, "message": "欠费次数不能为负数"}), 400
            except (ValueError, TypeError):
                # 如果转换失败，返回400错误
                return _main().jsonify({"success": False, "message": "欠费次数必须是整数"}), 400

            # ========== 步骤4：直接修改INI文件 (不查找用户) ==========
            try:
                # 构造INI文件路径 (全局变量 SCHOOL_ACCOUNTS_DIR 指向 school_accounts 目录)
                ini_file = os.path.join(
                    _main().SCHOOL_ACCOUNTS_DIR, f"{school_username}.ini")

                # 检查文件是否存在
                if not os.path.exists(ini_file):
                    return _main().jsonify({
                        "success": False,
                        "message": f"学校账号配置文件不存在: {school_username}"
                    }), 404

                # 读取配置文件
                config = configparser.RawConfigParser()
                config.optionxform = str
                config.read(ini_file, encoding='utf-8')

                # 确保 [stats] 节存在
                if not config.has_section('stats'):
                    config.add_section('stats')

                # 读取当前欠费次数（在修改前记录，用于后续账单同步）
                old_overdue_count = config.getint('stats', 'overdue_count', fallback=0)

                # 计算最终欠费次数：叠加模式则累加，否则直接覆盖
                if add_mode:
                    final_overdue_count = old_overdue_count + new_overdue_count
                else:
                    final_overdue_count = new_overdue_count

                # 更新欠费次数
                config.set('stats', 'overdue_count', str(final_overdue_count))

                # 保存文件
                with open(ini_file, 'w', encoding='utf-8') as f:
                    config.write(f)

                # 获取当前登录管理员（用于日志）
                admin_username = _main().g.user if hasattr(_main().g, 'user') else "unknown"
                # 兼容处理 g.user 可能是字典的情况
                if isinstance(admin_username, dict):
                    admin_username = admin_username.get(
                        "auth_username", "unknown")

                if add_mode:
                    logging.info(
                        f"[管理员操作] {admin_username} 手动添加欠费（叠加模式）- "
                        f"学校账号: {school_username}, 增加: {new_overdue_count}, "
                        f"最终欠费次数: {final_overdue_count}"
                    )
                else:
                    logging.info(
                        f"[管理员操作] {admin_username} 已直接修改INI文件 - "
                        f"学校账号: {school_username}, 新欠费次数: {final_overdue_count}"
                    )

                _write_payment_log(
                    user_id=admin_username,
                    order_id="",
                    action="admin_clear_overdue",
                    log_data={
                        "target_user": auth_username,
                        "school_username": school_username,
                        "new_overdue_count": final_overdue_count,
                        "add_mode": add_mode
                    }
                )

                # ========== 同步 User_Billing 账单记录 ==========
                # 使账单列表（billing/list）与欠费变更保持一致
                billing_root = os.path.join(
                    os.path.dirname(os.path.abspath(__file__)), "User_Billing"
                )
                try:
                    if add_mode:
                        # 叠加模式：管理员手动增加欠费 → 为每次新增欠费创建账单记录
                        if auth_username and os.path.isdir(billing_root):
                            try:
                                _bc = _main()._read_config_ini(_main().CONFIG_JSON_FILE) or _main()._get_default_config()
                                _cost = round(float(_bc.get(
                                    "Payment_Settings", "single_run_cost", fallback="1.0"
                                )), 2)
                            except Exception:
                                _cost = 1.0
                            for _ in range(new_overdue_count):
                                _main()._create_user_billing_record(
                                    auth_username, school_username,
                                    "管理员手动添加欠费", _cost
                                )
                    else:
                        # 覆盖模式：欠费次数减少 → 将对应数量的 pending 账单标记为 admin_cleared
                        cleared_count = max(0, old_overdue_count - final_overdue_count)
                        if cleared_count > 0:
                            # 确定要搜索的账单目录列表
                            if auth_username:
                                search_dirs = [os.path.join(billing_root, auth_username)]
                            else:
                                # auth_username 未知时遍历所有用户目录
                                search_dirs = [
                                    os.path.join(billing_root, d)
                                    for d in os.listdir(billing_root)
                                    if os.path.isdir(os.path.join(billing_root, d))
                                ] if os.path.isdir(billing_root) else []

                            updated = 0
                            for user_dir in search_dirs:
                                if updated >= cleared_count:
                                    break
                                if not os.path.isdir(user_dir):
                                    continue
                                # 收集该用户目录下匹配的 pending 账单，按时间升序处理
                                candidates = []
                                for fname in os.listdir(user_dir):
                                    if not fname.endswith(".json"):
                                        continue
                                    fpath = os.path.join(user_dir, fname)
                                    try:
                                        with open(fpath, "r", encoding="utf-8") as _f:
                                            rec = json.load(_f)
                                        if (rec.get("school_username") == school_username
                                                and rec.get("status") == "pending"):
                                            candidates.append((rec.get("created_at", ""), fpath, rec))
                                    except Exception:
                                        pass
                                candidates.sort(key=lambda x: x[0])
                                for _, fpath, rec in candidates:
                                    if updated >= cleared_count:
                                        break
                                    rec["status"] = "admin_cleared"
                                    rec["admin_cleared_by"] = admin_username
                                    rec["admin_cleared_at"] = _main()._billing_now_utc_string()
                                    rec["admin_cleared_at_beijing"] = _main()._billing_now_beijing_string()
                                    try:
                                        with open(fpath, "w", encoding="utf-8") as _f:
                                            json.dump(rec, _f, indent=2, ensure_ascii=False)
                                        updated += 1
                                    except Exception as _e:
                                        logging.warning(f"[账单同步] 更新账单文件失败: {fpath}: {_e}")
                            logging.info(
                                f"[账单同步] 已将 {updated}/{cleared_count} 条账单状态更新为 admin_cleared"
                                f"（学校账号: {school_username}）"
                            )

                        # 覆盖模式：欠费次数增加 → 同步创建新的账单记录
                        added_count = max(0, final_overdue_count - old_overdue_count)
                        if added_count > 0 and auth_username:
                            if os.path.isdir(billing_root):
                                try:
                                    _bc = _main()._read_config_ini(_main().CONFIG_JSON_FILE) or _main()._get_default_config()
                                    _cost = round(float(_bc.get(
                                        "Payment_Settings", "single_run_cost", fallback="1.0"
                                    )), 2)
                                except Exception:
                                    _cost = 1.0
                                for _ in range(added_count):
                                    _main()._create_user_billing_record(
                                        auth_username, school_username,
                                        "管理员修正欠费次数（增加）", _cost
                                    )
                                logging.info(
                                    f"[账单同步] 已为用户 {auth_username} 创建 {added_count} 条新账单记录"
                                    f"（学校账号: {school_username}）"
                                )
                except Exception as _sync_e:
                    # 账单同步失败不影响主流程
                    logging.error(f"[账单同步] 同步 User_Billing 失败: {_sync_e}", exc_info=True)

                return _main().jsonify({
                    "success": True,
                    "message": f"已将学校账号 {school_username} 的欠费次数更新为 {final_overdue_count}"
                })

            except Exception as e:
                logging.error(f"[管理员操作] 修改INI文件失败: {str(e)}", exc_info=True)
                return _main().jsonify({
                    "success": False,
                    "message": f"操作失败: {str(e)}"
                }), 500

        except Exception as e:
            # ========== 异常处理 ==========

            # 捕获所有未预期的异常
            # 记录ERROR级别日志，包含异常信息
            logging.error(f"[管理员操作] 清除欠费异常: {str(e)}")

            # 记录完整的异常堆栈信息，便于调试
            logging.error(traceback.format_exc())

            # 返回500错误，告知前端服务器内部错误
            return _main().jsonify({
                "success": False,
                "message": f"操作失败: {str(e)}"
            }), 500

