    @app.route("/api/billing/list", methods=["GET"])
    @login_required
    def billing_list():
        """
        获取当前用户有权限学校账号的账单记录列表（按创建时间降序排列）。
        需要用户登录。
        """
        try:
            school_username = _main().request.args.get("school_username", "").strip()
            billing_root = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "User_Billing",
                "School_Bills",
            )

            # 仅允许读取当前用户有权限的学校账号账单
            try:
                allowed_schools = set((_main().g.api_instance._load_user_school_accounts(_main().g.user) or {}).keys())
            except Exception:
                allowed_schools = set()

            if school_username:
                if school_username not in allowed_schools:
                    return _main().jsonify({"success": True, "records": [], "total": 0})
                target_schools = [school_username]
            else:
                target_schools = sorted(allowed_schools)

            records = []

            def _load_school_name(_school_username: str) -> str:
                try:
                    for _backup_path in [
                        os.path.join(_main().SCHOOL_ACCOUNTS_DIR, _school_username, f"{_school_username}_backup.json"),
                        os.path.join(_main().SCHOOL_ACCOUNTS_DIR, f"{_school_username}_backup.json"),
                    ]:
                        if os.path.exists(_backup_path):
                            try:
                                with open(_backup_path, "r", encoding="utf-8") as f:
                                    backup_data = json.load(f)
                                _name = (
                                    ((backup_data.get("userInfo") or {}).get("name") or "").strip()
                                    or ((backup_data.get("deptInfo") or {}).get("name") or "").strip()
                                )
                                if _name:
                                    return _name
                            except Exception as _name_err:
                                logging.warning(
                                    f"[账单列表] 读取学校账号 {_school_username} 对应姓名失败: {_name_err}"
                                )
                except Exception as _name_err:
                    logging.warning(
                        f"[账单列表] 读取学校账号 {_school_username} 对应姓名失败: {_name_err}"
                    )
                return _school_username

            school_name_map = {
                school: _load_school_name(school) for school in target_schools
            }

            for school in target_schools:
                user_billing_dir = os.path.join(billing_root, school)
                if not os.path.isdir(user_billing_dir):
                    continue
                for filename in os.listdir(user_billing_dir):
                    if not filename.endswith(".json"):
                        continue
                    filepath = os.path.join(user_billing_dir, filename)
                    try:
                        with open(filepath, "r", encoding="utf-8") as f:
                            record = json.load(f)
                        try:
                            _main()._migrate_billing_file_beijing_times(filepath, record)
                        except Exception as _migration_err:
                            logging.warning(f"[账单列表] 迁移账单时间字段失败 {filename}: {_migration_err}")
                        record["school_name"] = school_name_map.get(
                            school, school
                        )
                        records.append(record)
                    except Exception as e:
                        logging.warning(f"[账单列表] 读取账单文件 {filename} 失败: {e}")

            # 按创建时间降序排列
            records.sort(key=lambda x: x.get("created_at", ""), reverse=True)

            for _r in records:
                if _r.get("amount") is not None:
                    try:
                        _r["amount"] = round(float(_r["amount"]), 2)
                    except Exception:  # nosec B110 - 金额格式化失败保留原值
                        pass
            return _main().jsonify({"success": True, "records": records, "total": len(records)})
        except Exception as e:
            logging.error(f"[账单列表] 获取账单列表失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"获取账单列表失败: {str(e)}"}), 500

    @app.route("/api/admin/billing/list", methods=["GET"])
    @admin_required
    def admin_billing_list():
        """
        管理员接口：获取有权限学校账号的账单记录列表。
        可选查询参数: school_username（指定学校账号）
        """
        try:
            school_username = _main().request.args.get("school_username", "").strip()
            keyword = _main().request.args.get("keyword", "").strip()
            page = max(1, int(_main().request.args.get("page", "1") or 1))
            page_size = max(1, min(100, int(_main().request.args.get("page_size", "50") or 50)))
            billing_root = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "User_Billing",
                "School_Bills",
            )
            records = []

            # 仅允许读取当前管理员有权限的学校账号账单
            try:
                allowed_schools = set((_main().g.api_instance._load_user_school_accounts(_main().g.user) or {}).keys())
            except Exception:
                allowed_schools = set()

            if school_username:
                if school_username not in allowed_schools:
                    return _main().jsonify({
                        "success": True,
                        "records": [],
                        "total": 0,
                        "summary": {
                            "total_count": 0,
                            "paid_count": 0,
                            "pending_count": 0,
                            "admin_cleared_count": 0,
                            "total_amount": 0.0,
                            "paid_amount": 0.0,
                            "pending_amount": 0.0,
                            "admin_cleared_amount": 0.0,
                        },
                        "page": page,
                        "page_size": page_size,
                    })
                target_schools = [school_username]
            else:
                target_schools = sorted(allowed_schools)

            def _load_admin_school_name(_school_username: str) -> str:
                try:
                    for _backup_path in [
                        os.path.join(_main().SCHOOL_ACCOUNTS_DIR, _school_username, f"{_school_username}_backup.json"),
                        os.path.join(_main().SCHOOL_ACCOUNTS_DIR, f"{_school_username}_backup.json"),
                    ]:
                        if os.path.exists(_backup_path):
                            try:
                                with open(_backup_path, "r", encoding="utf-8") as f:
                                    backup_data = json.load(f)
                                _name = (
                                    ((backup_data.get("userInfo") or {}).get("name") or "").strip()
                                    or ((backup_data.get("deptInfo") or {}).get("name") or "").strip()
                                )
                                if _name:
                                    return _name
                            except Exception as _name_err:
                                logging.warning(
                                    f"[管理员账单] 读取学校账号 {_school_username} 对应姓名失败: {_name_err}"
                                )
                except Exception as _name_err:
                    logging.warning(
                        f"[管理员账单] 读取学校账号 {_school_username} 对应姓名失败: {_name_err}"
                    )
                return _school_username

            school_name_map = {
                school: _load_admin_school_name(school) for school in target_schools
            }

            def _billing_matches_keyword(record, keyword):
                if not keyword:
                    return True
                keyword_lower = keyword.lower()
                haystack = [
                    str(record.get("school_username", "")),
                    str(record.get("school_name", "")),
                    str(record.get("reason", "")),
                    str(record.get("billing_id", "")),
                    str(record.get("order_id", "")),
                    str(record.get("payment_order_id", "")),
                    str(record.get("payment_trace_id", "")),
                    str(record.get("auth_username", "")),
                    str(record.get("nickname", "")),
                    str(record.get("phone", "")),
                ]
                combined = "\n".join(haystack).lower()
                return keyword_lower in combined

            for school in target_schools:
                user_billing_dir = os.path.join(billing_root, school)
                if not os.path.isdir(user_billing_dir):
                    continue
                for filename in os.listdir(user_billing_dir):
                    if not filename.endswith(".json"):
                        continue
                    filepath = os.path.join(user_billing_dir, filename)
                    try:
                        with open(filepath, "r", encoding="utf-8") as f:
                            record = json.load(f)
                        try:
                            _main()._migrate_billing_file_beijing_times(filepath, record)
                        except Exception as _migration_err:
                            logging.warning(f"[管理员账单] 迁移账单时间字段失败 {filename}: {_migration_err}")
                        record["school_name"] = school_name_map.get(school, school)
                        records.append(record)
                    except Exception as e:
                        logging.warning(f"[管理员账单] 读取账单文件 {filename} 失败: {e}")

            records.sort(key=lambda x: x.get("created_at", ""), reverse=True)
            for _r in records:
                if _r.get("amount") is not None:
                    try:
                        _r["amount"] = round(float(_r["amount"]), 2)
                    except Exception:  # nosec B110 - 金额格式化失败保留原值
                        pass

            filtered_records = [record for record in records if _billing_matches_keyword(record, keyword)]
            summary = {
                "total_count": len(filtered_records),
                "paid_count": 0,
                "pending_count": 0,
                "admin_cleared_count": 0,
                "total_amount": 0.0,
                "paid_amount": 0.0,
                "pending_amount": 0.0,
                "admin_cleared_amount": 0.0,
            }
            for record in filtered_records:
                amount = round(float(record.get("amount", 0) or 0), 2)
                status = str(record.get("status", "pending")).strip().lower()
                summary["total_amount"] += amount
                if status == "paid":
                    summary["paid_count"] += 1
                    summary["paid_amount"] += amount
                elif status == "admin_cleared":
                    summary["admin_cleared_count"] += 1
                    summary["admin_cleared_amount"] += amount
                else:
                    summary["pending_count"] += 1
                    summary["pending_amount"] += amount

            start_idx = (page - 1) * page_size
            end_idx = start_idx + page_size
            page_records = filtered_records[start_idx:end_idx]
            total = len(filtered_records)
            return _main().jsonify({"success": True, "records": page_records, "total": total, "summary": summary, "page": page, "page_size": page_size})
        except Exception as e:
            logging.error(f"[管理员账单] 获取账单列表失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"获取账单列表失败: {str(e)}"}), 500

    @app.route("/api/admin/billing/update", methods=["POST"])
    @admin_required
    def admin_billing_update():
        """
        管理员接口：修改账单信息（描述/状态/金额）。
        请求体:
        {
          "billing_id": "<账单ID>",
          "school_username": "<学校账号>",
          "reason": "<新描述，可选>",
          "status": "pending|paid|admin_cleared（可选）",
          "amount": 1.23（可选）
        }
        """
        try:
            data = _main().request.get_json() or {}
            billing_id = data.get("billing_id", "").strip()
            school_username = data.get("school_username", "").strip()

            if not billing_id or not school_username:
                return _main().jsonify({"success": False, "message": "billing_id 和 school_username 不能为空"}), 400

            allowed_schools = set((_main().g.api_instance._load_user_school_accounts(_main().g.user) or {}).keys())
            if school_username not in allowed_schools:
                return _main().jsonify({"success": False, "message": "无权操作该学校账号的账单"}), 403

            operator_username = _get_billing_operator_username()
            billing_dir = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "User_Billing",
                "School_Bills",
                school_username
            )
            billing_file = os.path.join(billing_dir, f"{billing_id}.json")

            if not os.path.exists(billing_file):
                return _main().jsonify({"success": False, "message": "账单记录不存在"}), 404

            with open(billing_file, "r", encoding="utf-8") as f:
                record = json.load(f)

            old_reason = str(record.get("reason", ""))
            old_amount = round(float(record.get("amount", 0) or 0), 2)
            old_status = str(record.get("status", "pending")).strip().lower()
            changed_fields = []
            now_utc = _main()._billing_now_utc_string()
            now_beijing = _main()._billing_now_beijing_string()

            if "reason" in data:
                new_reason = str(data.get("reason", "")).strip()
                if new_reason != str(record.get("reason", "")):
                    record["reason"] = new_reason
                    record["reason_updated_at"] = now_utc
                    record["reason_updated_at_beijing"] = now_beijing
                    record["reason_updated_by"] = _main().g.user
                    changed_fields.append("reason")

            if "amount" in data and str(data.get("amount", "")).strip() != "":
                try:
                    new_amount = round(float(data.get("amount")), 2)
                    if new_amount <= 0:
                        return _main().jsonify({"success": False, "message": "金额必须大于 0"}), 400
                except (TypeError, ValueError):
                    return _main().jsonify({"success": False, "message": "amount 必须是有效数字"}), 400
                if new_amount != old_amount:
                    record["amount"] = new_amount
                    changed_fields.append("amount")

            if "status" in data and str(data.get("status", "")).strip():
                new_status = str(data.get("status", "")).strip().lower()
                valid_status = {"pending", "paid", "admin_cleared"}
                if new_status not in valid_status:
                    return _main().jsonify({"success": False, "message": "status 必须是 pending/paid/admin_cleared"}), 400

                if new_status == "admin_cleared" and old_status != "pending":
                    return _main().jsonify({"success": False, "message": "只有待支付账单才能被管理员清除"}), 400
                if old_status == "admin_cleared" and new_status == "admin_cleared":
                    return _main().jsonify({"success": False, "message": "该账单已被管理员清除，请勿重复操作"}), 400

                if new_status != old_status:
                    record["status"] = new_status
                    changed_fields.append("status")

                    if new_status == "paid":
                        record["paid_at"] = now_utc
                        record["paid_at_beijing"] = now_beijing
                        record["paid_by"] = _main().g.user
                    elif old_status == "paid":
                        record.pop("paid_by", None)
                        record.pop("paid_at_beijing", None)
                        record["paid_at"] = ""

                    if new_status == "admin_cleared":
                        record["admin_cleared_at"] = now_utc
                        record["admin_cleared_at_beijing"] = now_beijing
                        record["admin_cleared_by"] = _main().g.user
                    elif old_status == "admin_cleared":
                        record.pop("admin_cleared_at", None)
                        record.pop("admin_cleared_at_beijing", None)
                        record.pop("admin_cleared_by", None)

            if not changed_fields:
                return _main().jsonify({"success": False, "message": "未检测到可更新内容"}), 400

            record["updated_at"] = now_utc
            record["updated_at_beijing"] = now_beijing
            record["updated_by"] = _main().g.user

            with open(billing_file, "w", encoding="utf-8") as f:
                json.dump(record, f, indent=2, ensure_ascii=False)

            if "amount" in changed_fields:
                _write_billing_log(
                    "billing_amount_changed",
                    record,
                    operator_username,
                    before={"amount": old_amount},
                    after={"amount": record.get("amount")},
                )
            if "status" in changed_fields:
                event_type = "billing_admin_cleared" if record.get("status") == "admin_cleared" else "billing_status_changed"
                _write_billing_log(
                    event_type,
                    record,
                    operator_username,
                    before={"status": old_status},
                    after={"status": record.get("status")},
                )
            if "reason" in changed_fields:
                _write_billing_log(
                    "billing_reason_changed",
                    record,
                    operator_username,
                    before={"reason": old_reason},
                    after={"reason": record.get("reason")},
                )

            _main().auth_system.log_audit(
                _main().g.user,
                "admin_update_billing",
                f"修改学校账号 {school_username} 账单 {billing_id} 字段: {', '.join(changed_fields)}",
            )
            logging.info(f"[管理员账单] 管理员 {g.user} 修改账单 {billing_id} 字段: {', '.join(changed_fields)}")
            return _main().jsonify({"success": True, "message": "账单已更新", "changed_fields": changed_fields})
        except Exception as e:
            logging.error(f"[管理员账单] 修改账单失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"修改账单失败: {str(e)}"}), 500

    @app.route("/api/admin/billing/delete", methods=["POST"])
    @admin_required
    def admin_billing_delete():
        """
        管理员接口：删除账单（软删除，移动到 ./User_Billing/Reomve/ 目录）。
        请求体: {"billing_id": "<账单ID>", "school_username": "<学校账号>"}
        """
        try:
            data = _main().request.get_json() or {}
            billing_id = str(data.get("billing_id", "")).strip()
            school_username = str(data.get("school_username", "")).strip()

            if not billing_id or not school_username:
                return _main().jsonify({"success": False, "message": "billing_id 和 school_username 不能为空"}), 400

            allowed_schools = set((_main().g.api_instance._load_user_school_accounts(_main().g.user) or {}).keys())
            if school_username not in allowed_schools:
                return _main().jsonify({"success": False, "message": "无权操作该学校账号的账单"}), 403

            billing_file = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "User_Billing",
                "School_Bills",
                school_username,
                f"{billing_id}.json"
            )
            if not os.path.exists(billing_file):
                return _main().jsonify({"success": False, "message": "账单记录不存在"}), 404

            operator_username = _get_billing_operator_username()
            deleted_record = _read_billing_record_by_school_username(school_username, billing_id) or {
                "billing_id": billing_id,
                "school_username": school_username,
            }

            remove_dir = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "User_Billing",
                "Reomve",
                school_username,
            )
            os.makedirs(remove_dir, exist_ok=True)
            target_file = os.path.join(remove_dir, f"{billing_id}.json")
            if os.path.exists(target_file):
                suffix = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S")
                target_file = os.path.join(remove_dir, f"{billing_id}_{suffix}.json")

            shutil.move(billing_file, target_file)
            _write_billing_log(
                "billing_deleted",
                deleted_record,
                operator_username,
                details=f"账单已移动到 {target_file}",
                before={"status": deleted_record.get("status")},
                after={"status": "deleted"},
            )
            _main().auth_system.log_audit(
                _main().g.user,
                "admin_delete_billing",
                f"删除学校账号 {school_username} 账单 {billing_id}，移动到 {target_file}",
            )
            logging.info(f"[管理员账单] 管理员 {g.user} 删除账单 {billing_id} -> {target_file}")
            return _main().jsonify({"success": True, "message": "账单已删除（已移动到 Reomve 目录）"})
        except Exception as e:
            logging.error(f"[管理员账单] 删除账单失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"删除账单失败: {str(e)}"}), 500

    @app.route("/api/admin/billing/logs", methods=["GET"])
    @admin_required
    def admin_billing_logs():
        try:
            keyword = _main().request.args.get("keyword", "").strip()
            event_type = _main().request.args.get("event_type", "").strip()
            page = max(1, int(_main().request.args.get("page", "1") or 1))
            page_size = max(1, min(100, int(_main().request.args.get("page_size", "50") or 50)))
            logs = []
            if os.path.exists(BILLING_LOGS_DIR):
                for filename in os.listdir(BILLING_LOGS_DIR):
                    if not filename.endswith(".json"):
                        continue
                    log_path = os.path.join(BILLING_LOGS_DIR, filename)
                    if not os.path.isfile(log_path):
                        continue
                    try:
                        with open(log_path, "r", encoding="utf-8") as fp:
                            payload = json.load(fp)
                    except Exception:
                        continue
                    if event_type and str(payload.get("event_type", "")).strip().lower() != event_type.lower():
                        continue
                    if not _billing_log_matches_keyword(payload, keyword):
                        continue
                    logs.append(payload)
            logs.sort(key=_safe_billing_log_sort_key, reverse=True)
            total = len(logs)
            start_idx = (page - 1) * page_size
            page_logs = logs[start_idx:start_idx + page_size]
            return _main().jsonify({"success": True, "logs": page_logs, "total": total, "page": page, "page_size": page_size})
        except Exception as e:
            logging.error(f"[管理员账单] 获取账单日志失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"获取账单日志失败: {str(e)}"}), 500

    @app.route("/api/admin/billing/add", methods=["POST"])
    @login_required
    @admin_required
    def admin_billing_add():
        """
        管理员接口：直接为指定用户创建账单记录。
        支持两种模式：
          - count（次数模式，默认）：指定欠费次数，金额 = 次数 × single_run_cost
          - amount（金额模式）：直接指定自定义金额

        请求体 JSON:
        {
          "auth_username": "user123",      // 目标用户名（必填）
          "school_username": "2021001",   // 学校账号（必填）
          "mode": "count",                // "count"（默认）或 "amount"
          "count": 1,                     // 次数（mode=count 时使用）
          "amount": 5.0,                  // 金额（mode=amount 时使用）
          "reason": "手动补录欠费"         // 原因（为空时自动生成）
        }

        返回:
          {"success": true, "billing_id": "...", "message": "账单已创建"}
        """
        try:
            data = _main().request.get_json() or {}
            school_username = str(data.get("school_username", "")).strip()
            mode = str(data.get("mode", "count")).strip().lower()
            reason = str(data.get("reason", "")).strip()

            if not school_username:
                return _main().jsonify({"success": False, "message": "school_username 不能为空"}), 400

            allowed_schools = set((_main().g.api_instance._load_user_school_accounts(_main().g.user) or {}).keys())
            if school_username not in allowed_schools:
                return _main().jsonify({"success": False, "message": "无权为该学校账号创建账单"}), 403

            if mode not in ("count", "amount"):
                return _main().jsonify({"success": False, "message": "mode 必须是 'count' 或 'amount'"}), 400

            admin_username = _main().g.user if hasattr(_main().g, "user") else "unknown"
            if isinstance(admin_username, dict):
                admin_username = admin_username.get("auth_username", "unknown")

            if mode == "count":
                try:
                    count = int(data.get("count", 1))
                    if count < 1:
                        return _main().jsonify({"success": False, "message": "次数必须大于 0"}), 400
                except (ValueError, TypeError):
                    return _main().jsonify({"success": False, "message": "次数必须是正整数"}), 400

                # 从配置读取单次费用
                try:
                    _cfg = _main()._read_config_ini(_main().CONFIG_FILE)
                    single_run_cost = round(float(_cfg.get("Payment_Settings", "single_run_cost", fallback="1.0")), 2) if _cfg else 1.0
                except Exception:
                    single_run_cost = 1.0

                total_amount = round(single_run_cost * count, 2)
                if not reason:
                    reason = f"管理员补录：{_main()._build_run_billing_reason(count, single_run_cost)}"

            else:  # amount mode
                try:
                    total_amount = round(float(data.get("amount", 0)), 2)
                    if total_amount <= 0:
                        return _main().jsonify({"success": False, "message": "金额必须大于 0"}), 400
                except (ValueError, TypeError):
                    return _main().jsonify({"success": False, "message": "金额必须是有效数字"}), 400

                if not reason:
                    reason = f"管理员手动添加账单 ¥{total_amount}"

            billing_id = _main()._create_user_billing_record("", school_username, reason, total_amount)
            if not billing_id:
                return _main().jsonify({"success": False, "message": "创建账单记录失败，请检查日志"}), 500

            created_record = _read_billing_record_by_school_username(school_username, billing_id) or {
                "billing_id": billing_id,
                "school_username": school_username,
                "amount": total_amount,
                "reason": reason,
                "status": "pending",
            }
            _write_billing_log(
                "billing_created",
                created_record,
                admin_username,
                details=f"管理员创建账单，模式={mode}",
                after={
                    "amount": created_record.get("amount"),
                    "status": created_record.get("status"),
                    "reason": created_record.get("reason"),
                },
            )

            _main().auth_system.log_audit(
                admin_username,
                "admin_add_billing",
                f"为学校账号 {school_username} 创建账单: {billing_id}, "
                f"模式={mode}, 金额=¥{total_amount}, 原因={reason!r}",
            )
            logging.info(
                f"[管理员账单] {admin_username} 为 {school_username} "
                f"创建账单 {billing_id}，模式={mode}，金额=¥{total_amount}"
            )
            return _main().jsonify({
                "success": True,
                "billing_id": billing_id,
                "amount": total_amount,
                "message": f"账单已创建（¥{total_amount}）",
            })
        except Exception as e:
            logging.error(f"[管理员账单] 创建账单失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"创建账单失败: {str(e)}"}), 500

    @app.route("/api/admin/restore_account", methods=["POST"])
    @admin_required
    def admin_restore_account():
        """
        管理员接口：从 Remove_Acoount 恢复已删除的用户账号。
        请求体:
          {
            "auth_username": "<备份中的原用户名>",
            "restore_as": "<恢复后使用的用户名，可选，默认同 auth_username>",
            "phone_override": "<新手机号，可选；空字符串表示强制清空手机号>",
            "force_phone_clear": true  // 可选，为 true 时强制清空手机号
          }
        冲突响应（409）：
          {"success": false, "conflict": "username"|"phone",
           "conflicting_user": "...", "phone": "...", "message": "..."}
        """
        try:
            data = _main().request.get_json()
            if not data:
                return _main().jsonify({"success": False, "message": "请求体不能为空"}), 400

            auth_username = data.get("auth_username", "").strip()
            if not auth_username:
                return _main().jsonify({"success": False, "message": "auth_username 不能为空"}), 400

            # restore_as: 恢复后使用的用户名（默认与备份用户名相同）
            restore_as = data.get("restore_as", "").strip() or auth_username
            # phone_override: 覆盖手机号（None=不覆盖；""=清空；其他=新手机号）
            phone_override = data.get("phone_override", None)
            if phone_override is not None:
                phone_override = str(phone_override).strip()
            force_phone_clear = bool(data.get("force_phone_clear", False))

            # 确定 Remove_Acoount 目录路径
            remove_account_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Remove_Acoount")
            index_path = os.path.join(remove_account_dir, "_index.json")

            # 检查索引文件是否存在
            if not os.path.exists(index_path):
                return _main().jsonify({"success": False, "message": "没有找到删除记录索引"}), 404

            # 读取索引
            with open(index_path, "r", encoding="utf-8") as f:
                ra_index = json.load(f)

            removed_accounts = ra_index.get("removed_accounts", {})
            if auth_username not in removed_accounts:
                return _main().jsonify({"success": False, "message": f"未找到用户 {auth_username} 的删除记录"}), 404

            # 获取备份文件名
            entry = removed_accounts[auth_username]
            backup_file = entry.get("backup_file", "")
            backup_path = os.path.join(remove_account_dir, backup_file)

            if not os.path.exists(backup_path):
                return _main().jsonify({"success": False, "message": f"备份文件不存在: {backup_file}"}), 404

            # 读取备份数据
            with open(backup_path, "r", encoding="utf-8") as f:
                backup_data = json.load(f)

            user_data = backup_data.get("user_data", {})
            school_accounts_data = backup_data.get("school_accounts")
            permissions_data = backup_data.get("permissions", {})

            if not user_data:
                return _main().jsonify({"success": False, "message": "备份数据损坏：缺少用户数据"}), 500

            # ── 读取 system_accounts/_index.json（用于冲突双重检测）──────────
            sys_index_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "system_accounts", "_index.json")
            sys_index_data = {}
            if os.path.exists(sys_index_path):
                try:
                    with open(sys_index_path, "r", encoding="utf-8") as f:
                        sys_index_data = json.load(f)
                except Exception:
                    sys_index_data = {}
            sys_accounts = sys_index_data.get("accounts", {})  # {username: hash}

            # ── 冲突检测 1：用户名是否已存在（文件 + 索引双重校验）────────────
            # 1a. 用户名已在索引中出现 → 用户名冲突
            if restore_as in sys_accounts:
                return _main().jsonify({
                    "success": False,
                    "conflict": "username",
                    "conflicting_username": restore_as,
                    "message": f"用户名 {restore_as} 已存在，请更换用户名后重试"
                }), 409
            # 1b. 文件系统中存在对应文件（兜底，防止索引与文件不同步）
            target_hash = hashlib.sha256(str(restore_as).encode()).hexdigest()
            target_user_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "system_accounts", f"{target_hash}.json")
            if os.path.exists(target_user_file):
                return _main().jsonify({
                    "success": False,
                    "conflict": "username",
                    "conflicting_username": restore_as,
                    "message": f"用户名 {restore_as} 已存在，请更换用户名后重试"
                }), 409

            # ── UUID 冲突检测：目标 hash 是否已被另一用户名占用 ────────────────
            # （理论上 sha256 不会碰撞，但若索引/文件不同步可能出现游离 hash）
            assigned_hash = target_hash  # 默认使用 sha256(restore_as)
            existing_owner = next(
                (uname for uname, uhash in sys_accounts.items() if uhash == target_hash),
                None
            )
            if existing_owner and existing_owner != restore_as:
                # UUID 冲突：该 hash 已被另一个用户名占用，重新分配一个随机 UUID
                new_uuid = str(uuid.uuid4())
                while (
                    os.path.exists(os.path.join(os.path.dirname(os.path.abspath(__file__)), "system_accounts", f"{new_uuid}.json"))
                    or new_uuid in sys_accounts.values()
                ):
                    new_uuid = str(uuid.uuid4())
                assigned_hash = new_uuid
                logging.warning(
                    f"[恢复账号] UUID 冲突：hash {target_hash[:8]}... 已被用户 {existing_owner} 占用，"
                    f"已为 {restore_as} 重新分配 UUID: {new_uuid[:8]}..."
                )

            # 最终目标文件路径（使用 assigned_hash，可能是重新分配的 UUID）
            target_user_file = os.path.join(
                os.path.dirname(os.path.abspath(__file__)), "system_accounts", f"{assigned_hash}.json"
            )

            # ── 冲突检测 2：手机号是否已被其他账号绑定 ────────────────────────
            original_phone = user_data.get("phone", "")
            effective_phone = original_phone  # 默认使用备份中的手机号

            if phone_override is not None:
                # 调用方已明确提供手机号覆盖（含空字符串）
                effective_phone = phone_override
            elif force_phone_clear:
                effective_phone = ""

            # 仅在有手机号时才检测冲突
            if effective_phone:
                phone_bound_to = _main().auth_system.find_user_by_phone(effective_phone)
                if phone_bound_to and phone_bound_to != restore_as:
                    return _main().jsonify({
                        "success": False,
                        "conflict": "phone",
                        "conflicting_user": phone_bound_to,
                        "phone": effective_phone,
                    "message": f"手机号 {effective_phone} 已被用户 {phone_bound_to} 绑定"
                }), 409

            # ── 应用修改并写入 ────────────────────────────────────────────────
            # 如果用户名有变更，更新 user_data 中的相关字段
            user_data["auth_username"] = restore_as
            if user_data.get("nickname") == auth_username:
                user_data["nickname"] = restore_as

            # 更新手机号
            user_data["phone"] = effective_phone

            # ── UUID 冲突处理：清理 session_ids ──────────────────────────────
            # 备份中的 session_ids 均已过期（账号删除时会话文件同步清除）。
            # 对仍残留的 session_id，检查是否与当前活跃会话冲突；
            # 存在冲突或已过期的 session_id 一律移除，确保账号以无活跃会话状态恢复。
            old_session_ids = user_data.get("session_ids", [])
            cleaned_session_ids = []
            reassigned_count = 0
            for sid in old_session_ids:
                session_file = _main().get_session_file_path(sid)
                if os.path.exists(session_file):
                    # 该 UUID 与现有会话文件冲突，丢弃（重新分配 = 不保留）
                    reassigned_count += 1
                    logging.warning(f"[恢复账号] session UUID 冲突，已丢弃: {sid[:8]}...")
                # 无论是否冲突，备份的 session_ids 均已失效，不再保留
            user_data["session_ids"] = cleaned_session_ids  # 恢复为空列表
            if old_session_ids:
                logging.info(
                    f"[恢复账号] 已清空 {len(old_session_ids)} 个过期 session UUID"
                    + (f"（其中 {reassigned_count} 个存在冲突）" if reassigned_count else "")
                )

            # 恢复用户文件到 system_accounts
            with open(target_user_file, "w", encoding="utf-8") as f:
                json.dump(user_data, f, indent=2, ensure_ascii=False)
            logging.info(f"[恢复账号] 已恢复用户文件（恢复为 {restore_as}）: {target_user_file}")

            # 恢复 school_accounts（如果有）
            if school_accounts_data:
                school_file = _main().auth_system._get_user_accounts_file(restore_as)
                try:
                    with open(school_file, "w", encoding="utf-8") as f:
                        json.dump(school_accounts_data, f, indent=2, ensure_ascii=False)
                    logging.info(f"[恢复账号] 已恢复学校账号文件")
                except Exception as e:
                    logging.warning(f"[恢复账号] 恢复学校账号失败: {e}")

            # 恢复权限配置
            if permissions_data:
                if "user_groups" in permissions_data:
                    _main().auth_system.permissions.setdefault("user_groups", {})[restore_as] = permissions_data["user_groups"]
                if "user_custom_permissions" in permissions_data:
                    _main().auth_system.permissions.setdefault("user_custom_permissions", {})[restore_as] = permissions_data["user_custom_permissions"]
                _main().auth_system._save_permissions()
                logging.info(f"[恢复账号] 已恢复权限配置")

            # 更新 system_accounts/_index.json（使用 assigned_hash，可能已重新分配）
            _main()._update_system_accounts_index(restore_as, assigned_hash, "add")

            # 从 Remove_Acoount/_index.json 中移除该记录
            del ra_index["removed_accounts"][auth_username]
            ra_index["updated_at"] = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            with open(index_path, "w", encoding="utf-8") as f:
                json.dump(ra_index, f, indent=2, ensure_ascii=False)

            # 删除备份文件
            try:
                os.remove(backup_path)
            except Exception as e:
                logging.warning(f"[恢复账号] 删除备份文件失败: {e}")

            restored_note = f"（原用户名: {auth_username}）" if restore_as != auth_username else ""
            phone_note = f"，手机号已{'清空' if not effective_phone else '修改'}" if effective_phone != original_phone else ""
            logging.info(f"[恢复账号] 用户 {restore_as}{restored_note} 已成功恢复{phone_note}")
            return _main().jsonify({"success": True, "message": f"用户 {restore_as} 已成功恢复{phone_note}", "restored_as": restore_as})

        except Exception as e:
            logging.error(f"[恢复账号] 恢复账号失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"恢复账号失败: {str(e)}"}), 500

    @app.route("/api/admin/removed_accounts", methods=["GET"])
    @admin_required
    def admin_list_removed_accounts():
        """
        管理员接口：列出所有已删除的账号记录。
        从 Remove_Acoount/_index.json 读取。
        """
        try:
            remove_account_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Remove_Acoount")
            index_path = os.path.join(remove_account_dir, "_index.json")

            if not os.path.exists(index_path):
                return _main().jsonify({"success": True, "removed_accounts": {}})

            with open(index_path, "r", encoding="utf-8") as f:
                ra_index = json.load(f)

            removed_accounts = ra_index.get("removed_accounts", {}) or {}
            enriched_accounts = {}
            for auth_username, entry in removed_accounts.items():
                item = {
                    "backup_file": entry.get("backup_file", ""),
                    "deleted_at": entry.get("deleted_at", ""),
                    "nickname": auth_username,
                    "avatar_url": "default_avatar.png",
                    "phone": "",
                    "created_at": None,
                    "last_login": None,
                    "last_login_ip": "",
                    "last_login_city": "未知",
                    "max_sessions": 1,
                    "available_runs": 0,
                    "2fa_enabled": False,
                }
                backup_file = entry.get("backup_file", "")
                backup_path = os.path.join(remove_account_dir, backup_file) if backup_file else ""
                if backup_path and os.path.exists(backup_path):
                    try:
                        with open(backup_path, "r", encoding="utf-8") as bf:
                            backup_data = json.load(bf)
                        user_data = backup_data.get("user_data", {}) or {}
                        item["nickname"] = user_data.get("nickname", auth_username) or auth_username
                        item["avatar_url"] = user_data.get("avatar_url", "default_avatar.png") or "default_avatar.png"
                        item["phone"] = user_data.get("phone", "") or ""
                        item["created_at"] = user_data.get("created_at")
                        item["last_login"] = user_data.get("last_login")
                        item["last_login_ip"] = user_data.get("last_login_ip", "") or ""
                        item["last_login_city"] = user_data.get("last_login_city", "未知") or "未知"
                        item["max_sessions"] = user_data.get("max_sessions", 1)
                        item["available_runs"] = user_data.get("available_runs", 0)
                        item["2fa_enabled"] = bool(user_data.get("2fa_enabled") or user_data.get("tfa_enabled"))
                    except Exception as e:
                        logging.warning(f"[已删除账号] 读取备份补充信息失败: {auth_username}, 错误: {e}")
                enriched_accounts[auth_username] = item

            return _main().jsonify({"success": True, "removed_accounts": enriched_accounts, "updated_at": ra_index.get("updated_at", "")})
        except Exception as e:
            logging.error(f"[已删除账号] 获取列表失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"获取已删除账号列表失败: {str(e)}"}), 500

    @app.route("/api/admin/removed_account_detail", methods=["GET"])
    @admin_required
    def admin_removed_account_detail():
        """
        管理员接口：获取单个已删除账号的详细信息。
        """
        try:
            auth_username = str(_main().request.args.get("auth_username", "")).strip()
            if not auth_username:
                return _main().jsonify({"success": False, "message": "auth_username 不能为空"}), 400

            remove_account_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Remove_Acoount")
            index_path = os.path.join(remove_account_dir, "_index.json")
            if not os.path.exists(index_path):
                return _main().jsonify({"success": False, "message": "未找到已删除账号索引"}), 404

            with open(index_path, "r", encoding="utf-8") as f:
                ra_index = json.load(f)
            removed_accounts = ra_index.get("removed_accounts", {}) or {}
            if auth_username not in removed_accounts:
                return _main().jsonify({"success": False, "message": f"未找到用户 {auth_username} 的删除记录"}), 404

            entry = removed_accounts.get(auth_username, {}) or {}
            backup_file = entry.get("backup_file", "")
            backup_path = os.path.join(remove_account_dir, backup_file) if backup_file else ""
            if not backup_path or not os.path.exists(backup_path):
                return _main().jsonify({"success": False, "message": f"备份文件不存在: {backup_file}"}), 404

            with open(backup_path, "r", encoding="utf-8") as bf:
                backup_data = json.load(bf)

            user_data = backup_data.get("user_data", {}) or {}
            school_accounts_data = backup_data.get("school_accounts", {}) or {}
            if not isinstance(school_accounts_data, dict):
                school_accounts_data = {}
            school_accounts = list(school_accounts_data.keys())

            permissions_snapshot = backup_data.get("permissions", {}) or {}
            if not isinstance(permissions_snapshot, dict):
                permissions_snapshot = {}
            snapshot_user_groups = permissions_snapshot.get("user_groups", {}) or {}
            if not isinstance(snapshot_user_groups, dict):
                snapshot_user_groups = {}
            snapshot_user_custom = permissions_snapshot.get("user_custom_permissions", {}) or {}
            if not isinstance(snapshot_user_custom, dict):
                snapshot_user_custom = {}

            user_group = (
                snapshot_user_groups.get(auth_username)
                or user_data.get("group")
                or "guest"
            )
            group_info = _main().auth_system.permissions.get("permission_groups", {}).get(user_group, {}) or {}
            group_permissions = group_info.get("permissions", {}) or {}
            if not isinstance(group_permissions, dict):
                group_permissions = {}
            user_custom_permissions = snapshot_user_custom.get(auth_username, {}) or {}
            if not isinstance(user_custom_permissions, dict):
                user_custom_permissions = {}
            added_permissions = [
                str(p).strip()
                for p in (user_custom_permissions.get("added", []) or [])
                if str(p).strip()
            ]
            removed_permissions = [
                str(p).strip()
                for p in (user_custom_permissions.get("removed", []) or [])
                if str(p).strip()
            ]
            effective_permissions = dict(group_permissions)
            for perm in added_permissions:
                effective_permissions[perm] = True
            for perm in removed_permissions:
                effective_permissions[perm] = False
            enabled_permissions = sorted(
                [k for k, v in effective_permissions.items() if bool(v)],
                key=lambda x: str(x),
            )

            current_messages = []
            messages_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "messages.json")
            if os.path.exists(messages_file):
                try:
                    with open(messages_file, "r", encoding="utf-8") as f:
                        all_messages = json.load(f)
                    if isinstance(all_messages, list):
                        current_messages = [
                            msg for msg in all_messages
                            if isinstance(msg, dict) and str(msg.get("auth_username") or "").strip() == auth_username
                        ]
                except Exception as e:
                    logging.warning(f"[已删除账号] 读取 messages.json 失败（忽略）: {e}")

            deleted_messages = []
            deleted_messages_file = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "logs",
                "deleted_messages.json",
            )
            if os.path.exists(deleted_messages_file):
                try:
                    with open(deleted_messages_file, "r", encoding="utf-8") as f:
                        deleted_log = json.load(f)
                    if isinstance(deleted_log, list):
                        deleted_messages = [
                            msg for msg in deleted_log
                            if isinstance(msg, dict) and str(msg.get("auth_username") or "").strip() == auth_username
                        ]
                except Exception as e:
                    logging.warning(f"[已删除账号] 读取 deleted_messages.json 失败（忽略）: {e}")

            message_items = []
            for msg in current_messages:
                message_items.append(
                    {
                        "id": msg.get("id", ""),
                        "content": msg.get("content", ""),
                        "timestamp": msg.get("timestamp"),
                        "ip": msg.get("ip", ""),
                        "source": "active",
                        "status_text": "现存",
                    }
                )
            for msg in deleted_messages:
                message_items.append(
                    {
                        "id": msg.get("id", ""),
                        "content": msg.get("content", ""),
                        "timestamp": msg.get("timestamp"),
                        "ip": msg.get("ip", ""),
                        "source": "deleted",
                        "status_text": "已删",
                        "deleted_at": msg.get("deleted_at"),
                        "deleted_by": msg.get("deleted_by", ""),
                        "deletion_reason": msg.get("deletion_reason", ""),
                    }
                )

            def _message_sort_key(item):
                primary = item.get("timestamp")
                if primary is None or primary == "":
                    primary = item.get("deleted_at", "")
                return str(primary)

            message_items.sort(key=_message_sort_key, reverse=True)
            message_items_limited = message_items[:50]

            billing_records = []
            billing_root = os.path.join(
                os.path.dirname(os.path.abspath(__file__)),
                "User_Billing",
                "School_Bills",
            )
            if os.path.isdir(billing_root):
                for school_username in school_accounts:
                    school_dir = os.path.join(billing_root, school_username)
                    if not os.path.isdir(school_dir):
                        continue
                    for filename in os.listdir(school_dir):
                        if not filename.endswith(".json"):
                            continue
                        bill_path = os.path.join(school_dir, filename)
                        try:
                            with open(bill_path, "r", encoding="utf-8") as bf:
                                bill = json.load(bf)
                            if not isinstance(bill, dict):
                                continue
                            try:
                                _main()._migrate_billing_file_beijing_times(bill_path, bill)
                            except Exception as _migration_err:
                                logging.warning(
                                    f"[已删除账号] 迁移账单时间字段失败（忽略）: {bill_path}, 错误: {_migration_err}"
                                )
                            amount = bill.get("amount")
                            try:
                                amount = round(float(amount), 2)
                            except Exception:
                                amount = 0.0
                            billing_records.append(
                                {
                                    "billing_id": bill.get("billing_id", os.path.splitext(filename)[0]),
                                    "school_username": bill.get("school_username", school_username) or school_username,
                                    "reason": bill.get("reason", ""),
                                    "amount": amount,
                                    "status": bill.get("status", "pending"),
                                    "created_at": bill.get("created_at"),
                                    "created_at_beijing": bill.get("created_at_beijing"),
                                    "paid_at": bill.get("paid_at"),
                                    "paid_at_beijing": bill.get("paid_at_beijing"),
                                    "payment_orders_count": len(bill.get("payment_orders", []) or []),
                                }
                            )
                        except Exception as e:
                            logging.warning(
                                f"[已删除账号] 读取账单失败（忽略）: {bill_path}, 错误: {e}"
                            )
            billing_records.sort(key=lambda x: str(x.get("created_at", "")), reverse=True)
            billing_records_limited = billing_records[:100]
            billing_stats = {
                "total": len(billing_records),
                "pending": 0,
                "paid": 0,
                "admin_cleared": 0,
                "other": 0,
                "total_amount": 0.0,
                "pending_amount": 0.0,
            }
            for rec in billing_records:
                status = str(rec.get("status", "")).strip().lower()
                if status == "pending":
                    billing_stats["pending"] += 1
                elif status == "paid":
                    billing_stats["paid"] += 1
                elif status == "admin_cleared":
                    billing_stats["admin_cleared"] += 1
                else:
                    billing_stats["other"] += 1
                amt = rec.get("amount", 0.0) or 0.0
                try:
                    amt = float(amt)
                except Exception:
                    amt = 0.0
                billing_stats["total_amount"] += amt
                if status == "pending":
                    billing_stats["pending_amount"] += amt
            billing_stats["total_amount"] = round(billing_stats["total_amount"], 2)
            billing_stats["pending_amount"] = round(billing_stats["pending_amount"], 2)

            detail = {
                "auth_username": user_data.get("auth_username", auth_username) or auth_username,
                "nickname": user_data.get("nickname", auth_username) or auth_username,
                "avatar_url": user_data.get("avatar_url", "default_avatar.png") or "default_avatar.png",
                "last_login_ip": user_data.get("last_login_ip", "") or "",
                "last_login": user_data.get("last_login"),
                "register_time": user_data.get("created_at"),
                "deleted_at": backup_data.get("deleted_at") or entry.get("deleted_at", ""),
                "school_accounts": school_accounts,
                "permission_group": {
                    "key": user_group,
                    "name": group_info.get("name", user_group) or user_group,
                },
                "permissions": {
                    "group_permissions": group_permissions,
                    "user_custom_permissions": {
                        "added": added_permissions,
                        "removed": removed_permissions,
                    },
                    "effective_permissions": effective_permissions,
                    "enabled_permissions": enabled_permissions,
                },
                "messages": {
                    "total_current": len(current_messages),
                    "total_deleted": len(deleted_messages),
                    "records": message_items_limited,
                },
                "billing": {
                    "stats": billing_stats,
                    "records": billing_records_limited,
                },
            }

            return _main().jsonify({"success": True, "detail": detail})
        except Exception as e:
            logging.error(f"[已删除账号] 获取详情失败: {e}", exc_info=True)
            return _main().jsonify({"success": False, "message": f"获取已删除账号详情失败: {str(e)}"}), 500

    @socketio.on("connect")
    def handle_connect():
        session_id = _main().request.args.get("session_id") or _main().request.cookies.get(
            "session_id_cookie"
        )
        if not session_id:
            session_id = _main().session.get("session_id")
        logging.info(f"WebSocket 客户端连接: {request.sid}")

    @socketio.on("join")
    def handle_join(data):
        if isinstance(data, str):
            try:
                data = json.loads(data)
            except Exception as e:
                logging.warning(
                    f"WebSocket 'join' 事件数据解析失败: {e}, 原始数据: {data}"
                )
                return
        if not isinstance(data, dict):
            logging.warning(f"WebSocket 'join' 接收到无效数据类型: {type(data)}")
            return
        session_id = data.get("session_id")
        if session_id:
            _main().join_room(session_id)
            logging.info(f"WebSocket 客户端 {request.sid} 成功加入 {session_id}")
            _main().emit("log_message", {"msg": "WebSocket 连接成功！"}, room=session_id)
        else:
            logging.warning(
                f"WebSocket 客户端 {request.sid} 加入房间失败：缺少 session_id。"
            )

    @socketio.on("heartbeat")
    def handle_heartbeat(data):
        _main().emit("heartbeat_ack", {"ts": time.time()})

    @socketio.on("disconnect")
    def handle_disconnect():
        logging.info(f"WebSocket 客户端断开连接: {request.sid}")

    def _emit_verification_codes_update(session_id):
        """辅助函数：向指定会话推送验证码列表更新事件"""
        if not session_id or not socketio:
            logging.debug(
                f"[SocketIO] 跳过 'verification_codes_updated' 推送（缺少 session_id 或 socketio）"
            )
            return
        try:
            socketio.emit("verification_codes_updated", {}, room=session_id)
            logging.debug(
                f"[SocketIO] 已向会话 {session_id[:8]}... 推送 'verification_codes_updated' 事件"
            )
        except Exception as e:
            logging.error(
                f"[SocketIO] 推送 'verification_codes_updated' 失败: {e}")

    def cleanup_sessions():
        """定期清理超过24小时无活动的会话，并强制执行内存会话数量限制"""
        current_thread = threading.current_thread()
        logging.info(f"[会话清理 Worker] 已在线程中启动: Thread[{current_thread.name}, id={current_thread.ident}]")
        logging.warning("[Eventlet 警告] 会话清理 worker 运行在独立线程中 - 避免使用 eventlet 操作")
        _main()._log_runtime_memory_diagnostics("cleanup_worker_start")
        while True:
            time.sleep(3600)
            try:
                current_time = time.time()
                expired_sessions = []
                _main()._cleanup_expired_sms_verification_codes(now_ts=current_time)

                with web_sessions_lock:
                    for session_id in list(web_sessions.keys()):
                        with session_activity_lock:
                            last_activity = session_activity.get(session_id, 0)
                            if current_time - last_activity > 86400:
                                expired_sessions.append(session_id)
                    remaining_sessions = len(
                        web_sessions) - len(expired_sessions)
                    if remaining_sessions > _main().MAX_MEMORY_SESSIONS:
                        with session_activity_lock:
                            active_sessions = [
                                sid
                                for sid in web_sessions.keys()
                                if sid not in expired_sessions
                            ]
                            sorted_sessions = sorted(
                                active_sessions,
                                key=lambda sid: session_activity.get(sid, 0),
                            )
                            sessions_to_remove = (
                                remaining_sessions - _main().MAX_MEMORY_SESSIONS
                            )
                            for session_id in sorted_sessions[:sessions_to_remove]:
                                expired_sessions.append(session_id)
                        logging.warning(
                            f"[会话清理] 内存会话数超过限制({_main().MAX_MEMORY_SESSIONS})，额外清理了 {sessions_to_remove} 个最旧会话"
                        )
                for session_id in expired_sessions:
                    try:
                        _main().cleanup_session(
                            session_id,
                            reason="expired_or_memory_limit",
                        )
                    except Exception as e:
                        logging.error(
                            "[会话清理] 清理会话 %s 时出错: %s",
                            session_id[:8],
                            e,
                            exc_info=True,
                        )

                if expired_sessions:
                    logging.info(
                        f"[会话清理] 本次清理了 {len(expired_sessions)} 个会话"
                    )
                    gc.collect()
                else:
                    with web_sessions_lock:
                        logging.debug(
                            f"[会话清理] 当前内存会话数: {len(web_sessions)}/{_main().MAX_MEMORY_SESSIONS}"
                        )
                _main()._log_runtime_memory_diagnostics("cleanup_worker_interval")
            except Exception as e:
                logging.error(f"[会话清理] 清理过程出错: {e}", exc_info=True)

    cleanup_thread = threading.Thread(target=cleanup_sessions, daemon=True, name="Session_Cleanup_Worker")
    current_thread = threading.current_thread()
    logging.info(f"[线程创建] 正在从 Thread[{current_thread.name}, id={current_thread.ident}] 创建会话清理线程")
    logging.warning("[Eventlet 警告] 会话清理线程在 eventlet.monkey_patch 之后创建 - 可能导致 greenlet 冲突")
    cleanup_thread.start()
    logging.info(f"[线程创建] 会话清理线程已启动: {cleanup_thread.name} (id={cleanup_thread.ident})")
    _sync_runtime_state()
    _main().start_midnight_runtime_maintenance_worker()
    logging.info("正在加载持久化会话...")
    _main().load_all_sessions(args)
    logging.info("正在启动会话监控...")
    _main().start_session_monitor()
    try:
        _main().start_background_auto_attendance(args)
    except Exception as e:
        logging.error(f"启动后台自动签到服务失败: {e}", exc_info=True)

    cleaned_sessions_count = 0
    with web_sessions_lock:
        for session_id, api_instance in web_sessions.items():
            try:
                if hasattr(api_instance, "stop_run_flag") and isinstance(
                    api_instance.stop_run_flag, threading.Event
                ):
                    api_instance.stop_run_flag.set()
                if hasattr(api_instance, "multi_run_stop_flag") and isinstance(
                    api_instance.multi_run_stop_flag, threading.Event
                ):
                    api_instance.multi_run_stop_flag.set()
                if hasattr(api_instance, "stop_auto_refresh") and isinstance(
                    api_instance.stop_auto_refresh, threading.Event
                ):
                    api_instance.stop_auto_refresh.set()
                if hasattr(api_instance, "stop_multi_auto_refresh") and isinstance(
                    api_instance.stop_multi_auto_refresh, threading.Event
                ):
                    api_instance.stop_multi_auto_refresh.set()
                if getattr(api_instance, "is_multi_account_mode", False) and hasattr(
                    api_instance, "accounts"
                ):
                    for acc in api_instance.accounts.values():
                        if hasattr(acc, "stop_event") and isinstance(
                            acc.stop_event, threading.Event
                        ):
                            acc.stop_event.set()
                        acc.worker_thread = None
                        if not api_instance._should_preserve_status(
                            acc.status_text, "待命"
                        ):
                            acc.status_text = "待命"
                if hasattr(api_instance, "auto_refresh_thread"):
                    api_instance.auto_refresh_thread = None
                if hasattr(api_instance, "multi_auto_refresh_thread"):
                    api_instance.multi_auto_refresh_thread = None
                api_instance.current_run_idx = -1
                api_instance._first_center_done = False

                cleaned_sessions_count += 1
            except Exception as e:
                logging.error(f"重置会话 {session_id[:8]}... 状态时出错: {e}")

    logging.info(f"已重置 {cleaned_sessions_count} 个会话的运行状态标志。")

    logging.info("正在检查并修正持久化的后台任务状态...")
    interrupted_task_files = 0
    if background_task_manager and os.path.exists(
        background_task_manager.task_storage_dir
    ):
        try:
            for filename in os.listdir(background_task_manager.task_storage_dir):
                if filename.endswith(".json"):
                    filepath = os.path.join(
                        background_task_manager.task_storage_dir, filename
                    )
                    try:
                        task_state = None
                        with open(filepath, "r", encoding="utf-8") as f:
                            task_state = json.load(f)
                        if task_state and task_state.get("status") == "running":
                            task_state["status"] = "stopped"
                            task_state["error"] = "程序意外重启导致任务中断。"
                            task_state["last_update"] = time.time()
                            with open(filepath, "w", encoding="utf-8") as f:
                                json.dump(task_state, f, indent=2,
                                          ensure_ascii=False)
                            interrupted_task_files += 1
                            logging.debug(
                                f"已将持久化的后台任务 {filename} 状态修正为 stopped。"
                            )

                    except (IOError, json.JSONDecodeError) as e:
                        logging.warning(
                            f"处理后台任务状态文件 {filename} 时出错: {e}，跳过此文件。"
                        )
                    except Exception as e:
                        logging.error(
                            f"更新后台任务状态文件 {filename} 时发生意外错误: {e}",
                            exc_info=True,
                        )

            if interrupted_task_files > 0:
                logging.info(
                    f"已修正 {interrupted_task_files} 个持久化的 'running' 后台任务状态为 stopped。"
                )
            else:
                logging.info("未发现需要修正状态的持久化后台任务文件。")
        except Exception as e:
            logging.error(f"检查持久化后台任务状态时发生错误: {e}", exc_info=True)
    else:
        logging.info("后台任务管理器未初始化或存储目录不存在，跳过持久化状态检查。")
    if background_task_manager:
        with background_task_manager.lock:
            initial_task_count = len(background_task_manager.tasks)
            background_task_manager.tasks.clear()
            logging.info(
                f"已清空后台任务管理器的内存状态（清理了 {initial_task_count} 个任务记录）。"
            )
    # SSL/HTTPS 由 nginx 在容器入口处处理（见 docker-entrypoint.sh）。
    # Flask 后端只以纯 HTTP 方式监听 127.0.0.1:5000，不再自行处理 TLS。
    logging.info("SSL/HTTPS 由 nginx 负责，Flask 后端以 HTTP 模式运行")

    # ============================================================================
    # 添加请求钩子：处理X-Forwarded-*头和HTTPS重定向
    # 这些钩子在每个请求处理之前执行
    # ============================================================================
    @app.before_request
    def inject_request_context_and_log_start():
        """
        为请求注入 request_id 并记录入口日志。
        """
        try:
            _main().g.request_start_time = time.perf_counter()
            incoming_request_id = _main().request.headers.get("X-Request-ID", "").strip()
            if incoming_request_id:
                _main().g.request_id = incoming_request_id[:128]
            else:
                _main().g.request_id = str(uuid.uuid4())

            is_noisy_path = (
                _main().request.path.startswith("/static/")
                or _main().request.path.startswith("/css/")
                or _main().request.path.startswith("/js/")
                or _main().request.path == "/health"
                or _main().request.path.endswith(".png")
                or _main().request.path.endswith(".jpg")
                or _main().request.path.endswith(".ico")
            )
            log_msg = (
                f"[请求开始] {request.method} {request.path} "
                f"query={request.query_string.decode('utf-8', errors='ignore')[:512]}"
            )
            if is_noisy_path:
                logging.debug(log_msg)
            else:
                logging.info(log_msg)
        except Exception:
            logging.exception("记录请求入口日志失败")

    @app.before_request
    def handle_forwarded_proto():
        """
        处理反向代理（nginx）转发的请求头。

        功能说明：
        1. 从X-Forwarded-For头获取真实客户端IP
        2. 检查X-Forwarded-Proto头，识别原始请求是HTTP还是HTTPS

        注意：HTTPS重定向已交由nginx处理（见docker-entrypoint.sh），
        此处只做IP解析。
        """
        peer_ip = _main().request.environ.get("REMOTE_ADDR") or _main().request.remote_addr
        real_ip = _main()._select_forwarded_client_ip(
            _main().request.headers.get("X-Forwarded-For", ""),
            peer_ip,
        )
        if real_ip:
            _main().request.environ["REMOTE_ADDR"] = real_ip
            logging.debug("真实客户端IP已设置为: %s", real_ip)

    @app.after_request
    def add_security_headers(response):
        """
        为所有响应添加安全相关的HTTP头。
        """
        response = _main()._harden_frontend_javascript_response_if_needed(response)
        request_id = getattr(_main().g, "request_id", None)
        if request_id:
            response.headers["X-Request-ID"] = str(request_id)

        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["X-Frame-Options"] = "SAMEORIGIN"
        response.headers["X-XSS-Protection"] = "1; mode=block"
        response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"

        start_time = getattr(_main().g, "request_start_time", None)
        if start_time is not None:
            duration_ms = (time.perf_counter() - start_time) * 1000
        else:
            duration_ms = -1

        is_noisy_path = (
            _main().request.path.startswith("/static/")
            or _main().request.path.startswith("/css/")
            or _main().request.path.startswith("/js/")
            or _main().request.path == "/health"
            or _main().request.path.endswith(".png")
            or _main().request.path.endswith(".jpg")
            or _main().request.path.endswith(".ico")
        )

        response_size = response.calculate_content_length()
        if response_size is None:
            response_size = -1

        access_msg = (
            f"[请求完成] {request.method} {request.path} "
            f"status={response.status_code} duration_ms={duration_ms:.2f} size={response_size}"
        )
        if response.status_code >= 500:
            logging.error(access_msg)
        elif response.status_code >= 400:
            logging.warning(access_msg)
        elif is_noisy_path:
            logging.debug(access_msg)
        else:
            logging.info(access_msg)
        return response

    # ============================================================================
    # 启动服务器
    # 根据SSL配置选择HTTP或HTTPS模式
    # ============================================================================
    _sync_runtime_state(include_ip_location=True)
    server_url = f"http://{args.host}:{args.port}"
    print(f"\n{'='*60}")
    print(f"  跑步助手 Web 版本已启动")
    print(f"  访问地址: {server_url}")
    print(f"  SSL/HTTPS: 由 nginx 负责（见 docker-entrypoint.sh）")
    print(f"  会话持久化已启用（服务器重启后保留登录状态）")
    print(f"  JS计算在服务器端Chrome中执行，提升安全性")
    print(f"  会话监控已启用（5分钟不活跃自动清理）")
    print(f"{'='*60}\n")

    # [修正] 启动UDP通知线程（无论SSL是否启用，都在服务器启动前准备好）
    # 将此逻辑移至 try 块之前，确保必然执行
    def trigger_udp_notification():
        # 直接调用具备重试逻辑的发送函数
        # 函数内部已有30秒的健康检查轮询，无需额外封装
        current_thread = threading.current_thread()
        logging.info(f"[UDP 通知 Worker] 已在线程中启动: Thread[{current_thread.name}, id={current_thread.ident}]")
        logging.warning("[Eventlet 警告] UDP 通知 worker 运行在独立线程中 - 避免使用 eventlet 操作")
        _main()._send_startup_notification_to_log_forwarder(args.host, args.port)

    current_thread = threading.current_thread()
    logging.info(f"[线程创建] 正在从 Thread[{current_thread.name}, id={current_thread.ident}] 创建 UDP 通知线程")
    logging.warning("[Eventlet 警告] UDP 通知线程在 eventlet.monkey_patch 之后创建 - 可能导致 greenlet 冲突")
    udp_notification_thread = threading.Thread(
        target=trigger_udp_notification, daemon=True, name="UDP_Startup_Notification"
    )
    udp_notification_thread.start()
    logging.info(f"[系统启动] UDP通知服务线程已启动: {udp_notification_thread.name} (id={udp_notification_thread.ident})")

    try:
        logging.info(f"正在启动带有 WebSocket 支持的 Web 服务器于 {server_url}")
        current_thread = threading.current_thread()
        logging.info(f"[SocketIO 运行] 准备从 Thread[{current_thread.name}, id={current_thread.ident}] 运行")

        # 获取并记录当前所有活动线程
        all_threads = threading.enumerate()
        logging.info(f"[线程状态] socketio.run 之前的活动线程数: {len(all_threads)}")
        for t in all_threads:
            logging.info(f"[线程状态]   - Thread[name={t.name}, id={t.ident}, daemon={t.daemon}, alive={t.is_alive()}]")

        @socketio.on("connect", namespace="/")
        def on_first_connect():
            """首次连接时触发UDP通知（仅执行一次，作为健康检查的补充）"""
            if not hasattr(on_first_connect, "notified"):
                on_first_connect.notified = True
                current_thread = threading.current_thread()
                logging.debug(f"[SocketIO] 客户端首次连接确认，来自 Thread[{current_thread.name}, id={current_thread.ident}]")

        # 启动SocketIO服务器（阻塞调用），SSL/HTTPS 由 nginx 处理
        logging.info("[SocketIO 运行] 正在调用 socketio.run() - 这将阻塞主线程...")
        socketio.run(app, host=args.host, port=args.port, debug=False, allow_unsafe_werkzeug=True)
        logging.info("[SocketIO 运行] socketio.run() 已返回")

    except KeyboardInterrupt:
        print(f"\n{'='*60}")
        print(f"  用户终止了程序 (Ctrl+C)")
        print(f"  正在清理资源并退出...")
        print(f"{'='*60}\n")
        logging.info("用户通过 Ctrl+C 停止了服务器")
        sys.exit(0)
    except OSError as e:
        if (
            "WinError 10013" in str(e)
            or "permission" in str(e).lower()
            or "访问权限" in str(e)
        ):
            print(f"\n{'='*60}")
            print(f"错误: 端口 {args.port} 被占用或无访问权限")
            print(f"")
            print(f"可能的原因：")
            print(f"  1. 端口已被其他程序使用")
            print(f"  2. Windows系统保留了该端口")
            print(f"  3. 需要管理员权限")
            print(f"")
            print(f"解决方法：")
            print(f"  方法1: 使用其他端口")
            print(f"    python main.py --port 8080")
            print(f"    python main.py --port 3000")
            print(f"")
            print(f"  方法2: 以管理员身份运行")
            print(f"    右键点击 PowerShell → 以管理员身份运行")
            print(f"")
            print(f"  方法3 (Windows): 检查并关闭占用端口的程序")
            print(f"    netstat -ano | findstr :{args.port}")
            print(f"    taskkill /PID <进程ID> /F")
            print(f"{'='*60}\n")
            logging.error(f"端口绑定失败: {e}")
        else:
            print(f"\n错误: 启动服务器失败 - {e}\n")
            logging.error(f"服务器启动失败: {e}", exc_info=True)
        sys.exit(1)
    except Exception as e:
        print(f"\n错误: 服务器运行时发生异常 - {e}\n")
        logging.error(f"服务器异常: {e}", exc_info=True)
        sys.exit(1)
    finally:
        pass
